/**
 * VIVA — КЛИЕНТСКАЯ ЛОГИКА TELEGRAM MINI APP
 *
 * С чего начать:
 * - Разметка и контейнеры: index.html
 * - Все цвета, отступы, эффекты: style.css (Ocean Glass в конце)
 * - Действия игрока, страницы, модальные окна: этот файл
 * - API и безопасность: main.py, auth.py и тематические Python-модули
 *
 * ВАЖНО: файл собран из нескольких исторических слоёв (v11, v14 и т.д.).
 * Поздние слои местами расширяют более ранние функции через обёртки
 * oldPaint / oldGo и подобные. Порядок этих слоёв менять нельзя.
 * Не удаляй обработчики только из-за похожих названий.
 */
// ===== layer: app.js =====
'use strict';
const $=id=>document.getElementById(id),tg=window.Telegram?.WebApp;
tg?.ready();tg?.expand();tg?.disableVerticalSwipes?.();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('ru-RU');
const chanceText=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:6})+'%';
let S,tab='fish',loc=0,category='rod',admin=false,lock=false,battle=null,offset=0,playersPage=0,playerQuery='',adminTarget=null;
const labels={rod:'Удочки',reel:'Катушки',line:'Леска',bait:'Приманки',spoon:'Колебалки',spinner:'Вертушки',cases:'Кейсы'};
const noticeColors={common:'#abb4c0',rare:'#4d9dff',improved:'#5fe1f4',epic:'#b87cff',legendary:'#ffd36b',mythic:'#ff687e',absolute:'#f4f7ff',info:'#57bbeb',success:'#64dfb0',error:'#ff6b7d'};
// Показывает уведомления в верхней части экрана.
function note(text,kind='info',title=''){
  if(kind==='info'&&String(text).startsWith('✅'))kind='success';
  const el=document.createElement('div');el.className='notice';el.style.setProperty('--notice-color',noticeColors[kind]||noticeColors.info);
  const icons={error:'!',success:'✓',info:'i'};el.innerHTML=`<span class="notice-icon">${icons[kind]||'✦'}</span><div><b>${esc(title||({error:'Что-то пошло не так',success:'Готово',info:'Viva Fishing'}[kind]||S?.catalog.rarities[kind]||'Новая награда'))}</b><p>${esc(text)}</p></div><button class="notice-close" aria-label="Закрыть уведомление">×</button><i class="notice-timer"></i>`;
  $('toast').prepend(el);const dismiss=()=>{if(el.classList.contains('leaving'))return;el.classList.add('leaving');setTimeout(()=>el.remove(),420)};el.querySelector('button').onclick=dismiss;setTimeout(dismiss,4800);while($('toast').children.length>3)$('toast').lastElementChild.remove();
}
const ask=text=>Promise.resolve(confirm(text));
const run=async fn=>{try{return await fn()}catch(e){note(e.message,'error')}};

// Единая точка запросов к FastAPI: передаёт авторизацию Telegram.
async function api(path,body){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),15000);try{const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Telegram-Init-Data':tg?.initData||''},body:body===undefined?undefined:JSON.stringify(body),signal:ctl.signal});const j=await r.json();if(!r.ok)throw Error(typeof j.detail==='string'?j.detail:j.detail?.message||'Ошибка запроса');return j}finally{clearTimeout(timer)}}
// Сохраняет актуальное состояние игры и синхронизирует часы.
function accept(state){S=state;offset=S.server_time*1000-Date.now()}
// Отправляет игровое действие и перерисовывает интерфейс.
async function action(path,body={}){if(lock)return;lock=true;try{const r=await api('/api/fishing/'+path,body);if(r.state)accept(r.state);if(path==='cast'){startBattle(r.battle);return}paint();if(r.reward){note(r.duplicate?`${r.reward.name}: дубликат продан за $${fmt(r.compensation)}`:`${r.reward.name} ×${r.quantity} · +35 EXP`,r.reward.rarity,r.duplicate?'Дубликат продан':'Новая снасть');showReward(r.reward,r);}else if(r.earned)note('Продано за '+fmt(r.earned)+' долларов','success','Улов продан');else if(path==='profile')note('Ник и аватар сохранены','success','Профиль обновлён');else if(path==='equip')note('Снасть установлена','success');else note('Готово','success')}catch(e){note(e.message,'error')}finally{lock=false}}
// Функция rarity: логика соответствующего элемента интерфейса.
function rarity(item){return `<span class="rarity ${esc(item.rarity)}">${esc(S.catalog.rarities[item.rarity])}</span>`}
// Рисует иллюстрацию рыбы или снасти из assets.
function itemArt(item,extra=''){if(!item.art)return `<span class="fallback-icon ${extra}">${esc(item.icon||'🎣')}</span>`;const a=item.art,[x,y,w,h]=a.rect,[sw,sh]=a.size;return `<span class="item-art ${extra}" role="img" aria-label="${esc(item.name)}" style="background-image:url('/assets/${a.atlas}_atlas.png');background-size:${sw/w*100}% ${sh/h*100}%;background-position:${x/(sw-w)*100}% ${y/(sh-h)*100}%"></span>`;}
// Функция itemRow: логика соответствующего элемента интерфейса.
function itemRow(item,button=''){return `<div class="item" style="--item-color:${noticeColors[item.rarity]||noticeColors.common}"><div class="icon">${itemArt(item)}</div><div class="grow"><h3>${esc(item.name)}</h3>${rarity(item)}${item.effect?`<small class="gear-effect">${esc(item.effect)}</small>`:''}${item.amount!==undefined?` <small>×${fmt(item.amount)}</small>`:''}</div>${button}</div>`}
// Обновляет шапку, навигацию и текущий игровой экран.
function paint(){if(!S)return;const p=S.player,l=S.level;$('header').innerHTML=`<div class="avatar" style="--progress:${l.level_xp/l.next_xp*100}%" onclick="go('profile')" role="button" tabindex="0" aria-label="Профиль, уровень ${l.level}"><span>${esc(p.avatar==='🏠'?'🎣':p.avatar)}</span><b>${l.level}</b></div><div><div class="brand">VIVA FISHING</div><div class="name">${esc(p.nickname||p.telegram_name)}</div></div><div class="wallet">$ ${fmt(p.coins)}</div>`;
const tabs=[['fish','🎣','Рыбалка'],['bag','🎒','Рюкзак'],['shop','📦','Кейсы'],['profile','👤','Профиль']];tabs.push(['chat','💬','Чат']);if(admin)tabs.push(['admin','⚙','Админ']);$('nav').innerHTML=tabs.map(([key,icon,name])=>`<button class="${tab===key?'active':''}" onclick="go('${key}')"><span>${icon}</span>${name}</button>`).join('');
if(tab==='fish')fishView();if(tab==='bag')bagView();if(tab==='shop')shopView();if(tab==='profile')profileView();if(tab==='admin')adminView();if(tab==='rewards')rewardsView();if(tab==='chat')chatView();}
// Переключает вкладки приложения.
function go(t){if(battle)return;tab=t;document.body.classList.toggle('adm',t==='admin');paint();if(t==='admin')Admin.load();if(t==='chat')loadChat();}
// Функция scene: логика соответствующего элемента интерфейса.
function scene(l){return `<div class="f-scene loc-${esc(l.key)}" id="water"><div class="f-scene-sun"></div><span class="f-hill one"></span><span class="f-hill two"></span><div class="f-boat">⛵</div><div class="f-water"><span></span><span></span><span></span></div><div class="f-scene-label"><small>VIVA · РЫБАЦКИЙ КЛУБ</small><b>${esc(l.name)}</b><small>${esc(l.subtitle)}</small></div><div class="scene-float">🎣</div><div class="scene-caption">${S.level.level<l.level?'🔒 Откроется на '+l.level+' уровне':'Твой следующий большой улов — здесь'}</div></div>`;}
// Карточки надетого снаряжения на экране рыбалки.
function equipmentView(){return `<section class="loadout"><div class="row"><div><div class="brand">ГОТОВ К ЗАБРОСУ</div><h2>Твоё снаряжение</h2></div><span class="tag">${S.gear.reduce((n,g)=>n+g.amount,0)} снастей</span></div><div class="equipment-grid">${Object.entries(labels).filter(([k])=>k!=='cases').map(([k,label])=>{const key=S.progress.equipment[k==='bait'?'tackle':k],g=S.catalog.gear.find(g=>g.key===key);return `<button class="equipment-slot" style="--slot-color:${noticeColors[g?.rarity]||'#385268'}" onclick="openEquipment('${k}')"><span class="slot-icon">${g?itemArt(g):({reel:'⚙️',line:'🧵',spoon:'🥄',spinner:'🌀'}[k]||'🪝')}</span><small>${label}</small><b>${esc(g?.name||'Выбрать снасть')}</b>${g?rarity(g):'<span class="rarity common">Пустой слот</span>'}<span class="slot-change">×${S.gear.find(i=>i.key===g?.key)?.amount||0}</span></button>`}).join('')}</div></section>`;}
// Открывает выбор экипировки.
function openEquipment(type){const items=S.gear.filter(g=>g.type===type);$('modal').hidden=false;$('modal').innerHTML=`<section class="equipment-sheet"><div class="row"><div><div class="brand">СНАРЯЖЕНИЕ</div><h2>${labels[type]}</h2></div><button class="ghost sm" onclick="closeModal()">✕</button></div><p class="m">${{rod:'Зона контроля и сила против рывков.',reel:'Скорость подмотки и сброс натяжения.',line:'Прочность и эластичность. При срыве теряется 1 шт.',bait:'Быстрее поклёвка, вес и шансы рыбы. При срыве теряется 1 шт.',spoon:'Стабилизирует движение и утомляет рыбу.',spinner:'Увеличивает окно подсечки и шанс находок.'}[type]}</p>${items.length?items.map(g=>itemRow(g,`<button class="sm ${Object.values(S.progress.equipment).includes(g.key)?'ghost':''}" onclick="equipFromMain('${g.key}')" ${Object.values(S.progress.equipment).includes(g.key)?'disabled':''}>${Object.values(S.progress.equipment).includes(g.key)?'Надето':'Надеть'}</button>`)).join(''):'<div class="empty-state"><span>📦</span><h3>Здесь пока пусто</h3><p>Новые снасти выпадают из кейсов.</p><button onclick="closeModal();go(&quot;shop&quot;)">Выбрать кейс</button></div>'}</section>`;}
// Функция equipFromMain: логика соответствующего элемента интерфейса.
async function equipFromMain(key){await action('equip',{gear_key:key});closeModal();}
// Функция closeModal: логика соответствующего элемента интерфейса.
function closeModal(){if(!battle)$('modal').hidden=true;}
// Функция showReward: логика соответствующего элемента интерфейса.
function showReward(g,r={}){$('modal').hidden=false;$('modal').innerHTML=`<section class="reward-card" style="--reward:${noticeColors[g.rarity]}"><div class="reward-rays"></div><div class="brand">${r.duplicate?'ДУБЛИКАТ · АВТОПРОДАЖА':'ТВОЯ НОВАЯ СНАСТЬ'}</div><div class="reward-icon">${itemArt(g,'reward-art')}</div>${rarity(g)}<h1>${esc(g.name)}</h1><p>${esc(g.effect||'')}</p>${r.duplicate?`<div class="duplicate-price">+$${fmt(r.compensation)}</div><p>Такая снасть уже есть. Компенсация зачислена в долларах.</p>`:`<p>Добавлено ×${r.quantity||1}. Выбери снасть на главном экране.</p>`}<button class="full" onclick="closeModal();go('fish')">К снаряжению</button></section>`;}
// Функция luckView: логика соответствующего элемента интерфейса.
function luckView(){return S.buff?.active?`<div class="luck-card"><span>🍀</span><div><b>Удача ×${S.buff.multiplier}</b><small>Эпические и более редкие рыбы и снасти</small></div><strong class="luck-countdown">${luckTime(S.buff.expires_at)}</strong></div>`:'';}
// Функция luckTime: логика соответствующего элемента интерфейса.
function luckTime(ts){const t=Math.max(0,Math.ceil(ts-(Date.now()+offset)/1000));return `${Math.floor(t/3600)?Math.floor(t/3600)+':':''}${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;}
let refreshingLuck=false;
setInterval(()=>{if(!S)return;document.querySelectorAll('.luck-countdown').forEach(el=>el.textContent=luckTime(S.buff.expires_at));if(S.buff?.active&&S.buff.expires_at<(Date.now()+offset)/1000&&!refreshingLuck){refreshingLuck=true;run(async()=>{accept(await api('/api/fishing/state'));if(!battle&&['fish','shop'].includes(tab))paint();else if(tab==='profile'&&$('profile-luck'))$('profile-luck').innerHTML=luckView();}).finally(()=>refreshingLuck=false);}},1000);
// Страница рыбалки: локация, попытки, снасти и заброс.
function fishView(){const l=S.locations[loc],locked=S.level.level<l.level;$('view').innerHTML=`${luckView()}<div class="section-heading"><div><span class="brand">ВЫБЕРИ СВОЙ БЕРЕГ</span><h1>На рыбалку</h1></div><span class="tag">${loc+1} / ${S.locations.length}</span></div><div class="scene-wrap">${scene(l)}<button class="scene-arrow prev" onclick="move(-1)" aria-label="Предыдущая локация">‹</button><button class="scene-arrow next" onclick="move(1)" aria-label="Следующая локация">›</button></div><div class="location-dots">${S.locations.map((l,i)=>`<button aria-label="${esc(l.name)}" class="${loc===i?'on':''}" onclick="loc=${i};fishView()"></button>`).join('')}</div><div class="cast-panel"><p>${esc(l.description)}</p><button class="full cast-button" id="cast" onclick="action('cast',{location:S.locations[loc].key})" ${locked?'disabled':''}>Забросить удочку</button><small>Поклёвка → подсечка → натяжение и подмотка</small></div><details class="panel fish-chances"><summary>🐟 Рыбы локации и текущие шансы</summary><p class="m">Учтены приманка, вертушка и клевер. Вес меняется внутри диапазона.</p>${(S.fish_odds?.[l.key]||[]).map(f=>`<div class="odds-row"><span>${esc(f.name)}<br>${rarity(f)} · ${f.min_kg}–${f.max_kg} кг</span><b>${chanceText(f.chance)}</b></div>`).join('')}</details><div class="attempts-banner">Забросов осталось <b>${S.attempts.remaining} / 5</b><small id="attempts-timer">Максимум 5 · восстановление +1 в минуту</small></div><div class="row quick-actions"><button class="ghost" onclick="go('rewards')">🎁 Награды</button><button class="ghost" onclick="go('chat')">💬 Общий чат</button></div>${equipmentView()}<button class="ghost full" style="margin-top:20px" onclick="action('rescue')">Аварийная леска и наживка</button><p class="hint">Если запас закончился и денег на кейс нет · раз в сутки</p>`;let x=0;$('water').addEventListener('touchstart',e=>x=e.changedTouches[0].clientX,{passive:true});$('water').addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-x;if(Math.abs(dx)>45)move(dx<0?1:-1)},{passive:true});cooldown();}

// Функция move: логика соответствующего элемента интерфейса.
function move(d){loc=(loc+d+S.locations.length)%S.locations.length;fishView()}
// Функция cooldown: логика соответствующего элемента интерфейса.
function cooldown(){const button=$('cast');if(!button||!S)return;const now=(Date.now()+offset)/1000,a=S.attempts,next=a.next_at||a.resets_at||0,extra=next&&now>=next?1+Math.floor((now-next)/60):0,remaining=Math.min(5,a.remaining+extra),nextAt=remaining<5?next+extra*60:0,locked=S.level.level<S.locations[loc].level;const count=document.querySelector('.attempts-banner b');if(count)count.textContent=remaining+' / 5';if($('attempts-timer'))$('attempts-timer').textContent=nextAt?'Следующая попытка через '+rewardTime(nextAt)+' · +1 в минуту':'Запас полный · максимум 5 попыток';button.disabled=!S.active&&(locked||remaining===0);button.textContent=S.active?'Продолжить заброс':locked?'Откроется на '+S.locations[loc].level+' уровне':remaining===0?'Следующая попытка через '+rewardTime(nextAt):'Забросить удочку';}setInterval(()=>cooldown(),1000);
let bagTab='fish';
// Рисует содержимое рюкзака.
function bagView(){const items=bagTab==='fish'?S.fish:S.finds;$('view').innerHTML=`<div class="section-heading"><div><div class="brand">ПЛОДЫ ТВОЕЙ РЫБАЛКИ</div><h1>Рюкзак</h1></div><span class="bag-emblem">🎒</span></div><div class="bag-tabs"><button class="${bagTab==='fish'?'on':''}" onclick="bagTab='fish';bagView()">🐟 Рыба <b>${S.fish.reduce((a,f)=>a+f.amount,0)}</b></button><button class="${bagTab==='finds'?'on':''}" onclick="bagTab='finds';bagView()">🐚 Находки <b>${S.finds.reduce((a,f)=>a+f.amount,0)}</b></button></div><section class="panel bag-content">${items.length?items.map(f=>itemRow(f,bagTab==='fish'?`<button class="ghost sm" onclick="action('sell',{fish_key:'${f.key}'})">Продать<br>${fmt(f.value*f.amount)} $</button>`:'')).join(''):`<div class="empty-state"><span>${bagTab==='fish'?'🐟':'🐚'}</span><h3>${bagTab==='fish'?'Первый улов ещё впереди':'Сокровища ждут под водой'}</h3><p>Отправляйся на рыбалку и пополни коллекцию.</p><button onclick="go('fish')">На рыбалку</button></div>`}</section>${bagTab==='fish'&&items.length?`<button class="full" onclick="action('sell',{fish_key:'all'})">Продать весь улов · ${fmt(S.fish.reduce((a,f)=>a+f.amount*f.value,0))} $</button>`:''}`;}

// Страница кейсов и магазина.
function shopView(){$('view').innerHTML=`${luckView()}<div class="section-heading"><div><div class="brand">СНАРЯЖАЙСЯ К БОЛЬШОМУ УЛОВУ</div><h1>Магазин кейсов</h1></div><span class="bag-emblem">📦</span></div><p class="m">Удочки, катушки и оснастка выпадают только из кейсов. Выбери свой — все шансы указаны до открытия.</p><div class="case-grid">${S.cases.map((c,i)=>`<article class="shop-case" style="--case-color:${['#60bcec','#9c8dff','#f5b85c','#f179ab'][i]}"><div class="case-art"><div class="case-orbit"></div><span>${['📦','🎁','🧰','🗝️'][i]}</span><b>VIVA</b></div><div class="case-info"><div class="brand">КОЛЛЕКЦИЯ ${String(i+1).padStart(2,'0')}</div><h2>${esc(c.name)}</h2><p>${c.rewards.length} возможных снастей · +35 EXP</p>${c.amount?`<span class="tag">У тебя ${c.amount} шт.</span>`:''}<button class="full" onclick="confirmCase('${c.key}')" ${!c.enabled?'disabled':''}>${!c.enabled?'Временно закрыт':c.amount?'Открыть свой кейс':'Открыть · '+fmt(c.price)+' $'}</button><details class="case-odds"><summary>Состав и шансы выпадения</summary>${c.rewards.map(g=>`<div class="odds-row"><span>${itemArt(g,'odds-art')} ${esc(g.name)}<br>${rarity(g)}<small>Дубликат → $${fmt(g.duplicate_sale)}</small></span><b>${chanceText(g.chance)}</b></div>`).join('')}</details></div></article>`).join('')}</div><p class="hint">Дубликаты продаются автоматически. Новые лески и приманки — по 3 шт. Шансы учитывают клевер.</p>`;}
// Функция confirmCase: логика соответствующего элемента интерфейса.
async function confirmCase(key){await run(async()=>{accept(await api('/api/fishing/state'));if(tab==='shop')shopView();const c=S.cases.find(c=>c.key===key);if(!c?.enabled)return note('Кейс временно недоступен','error');if(confirm(c.amount?`Открыть твой «${c.name}»?`:`Открыть «${c.name}» за ${fmt(c.price)} долларов?`))await action('case/open',{case_key:key,revision:c.revision});});}
let selectedAvatar='🎣';
// Профиль игрока.
function profileView(){const p=S.player,l=S.level;selectedAvatar=S.catalog.avatars.includes(p.avatar)?p.avatar:'🎣';$('view').innerHTML=`<div class="row"><h1>Твой профиль</h1><button class="ghost sm" onclick="go('rewards')">🎁 Награды</button></div><p>ID ${p.telegram_id} · с ${new Date(p.created_at*1000).toLocaleDateString('ru-RU')}</p><div id="profile-luck">${luckView()}</div><section class="panel profile-edit"><h2>Твой образ на берегу</h2><label for="nickname">Ник игрока</label><input id="nickname" minlength="3" maxlength="24" value="${esc(p.nickname||p.telegram_name)}" placeholder="От 3 до 24 символов"><div class="avatar-picker">${S.catalog.avatars.map(a=>`<button class="avatar-option ${a===selectedAvatar?'selected':''}" data-avatar="${a}" onclick="selectAvatar('${a}')" aria-label="Аватар ${a}">${a}</button>`).join('')}</div><button class="full" onclick="saveProfile()">Сохранить ник и аватар</button></section><div class="card"><div class="row"><h2>Уровень ${l.level}</h2><small>${fmt(l.level_xp)} / ${fmt(l.next_xp)} EXP</small></div><div class="meter"><div style="width:${l.level_xp/l.next_xp*100}%"></div></div><p>Всего опыта: ${fmt(l.xp)} · Рекорд: ${S.best_kg||0} кг</p><div class="grid">${[['Забросы',S.progress.casts],['Уловы',S.progress.catches],['Коллекция',S.discovered.length+' / '+S.catalog.fish.length],['Кейсы',S.cases.reduce((a,c)=>a+c.opened,0)]].map(([n,v])=>`<div class="stat"><strong>${esc(typeof v==='number'?fmt(v):v)}</strong><small>${n}</small></div>`).join('')}</div></div><h2>Атлас рыб · ${S.catalog.fish.length} видов</h2>${S.locations.map(loc=>`<details class="panel"><summary>${loc.icon} ${esc(loc.name)} · ${S.catalog.fish.filter(f=>f.location===loc.key&&S.discovered.includes(f.key)).length} / ${S.catalog.fish.filter(f=>f.location===loc.key).length}</summary>${S.catalog.fish.filter(f=>f.location===loc.key).map(f=>S.discovered.includes(f.key)?itemRow(f):`<div class="item">${itemArt(f)}<span class="grow">🔒 ${esc(f.name)}<br><small>${f.behavior_name} · ${f.min_kg}–${f.max_kg} кг</small></span>${rarity(f)}</div>`).join('')}</details>`).join('')}`;}
// Функция selectAvatar: логика соответствующего элемента интерфейса.
function selectAvatar(a){selectedAvatar=a;document.querySelectorAll('.avatar-option').forEach(el=>el.classList.toggle('selected',el.dataset.avatar===a));}
// Функция saveProfile: логика соответствующего элемента интерфейса.
async function saveProfile(){const nickname=$('nickname').value.trim();if(nickname.length<3||nickname.length>24)return note('Ник должен содержать 3–24 символа','error');await action('profile',{nickname,avatar:selectedAvatar});}
// Запускает мини-игру вываживания рыбы.
function startBattle(initial){let b=initial,position=.5,sequence=b.sequence??0,stopped=false,inFlight=false,reeling=true,hookRequested=false,raf;const m=$('modal');battle=b;m.hidden=false;m.innerHTML=`<section class="card battle battle-v5"><div class="row"><div class="brand">VIVA · ЖИВАЯ РЫБАЛКА</div><button class="ghost sm" id="pause-battle">Пауза</button></div><div class="phase-steps"><span id="step-waiting">1. Поклёвка</span><span id="step-bite">2. Подсечка</span><span id="step-fight">3. Вываживание</span></div><h1 id="battle-name">Ждём поклёвку…</h1><div id="battle-meta"></div><div class="waters battle-water" id="battle-water"><span id="battle-float" class="float">🎣</span><div id="rush-flash">РЫВОК</div></div><p id="battle-cue">Не торопись — следи за поплавком</p><button id="hook-button" class="full hook-button" hidden>ПОДСЕЧЬ!</button><div id="fight-controls" hidden><div class="track"><div id="zone" class="zone"></div><span id="marker" class="fish-marker">🐟</span></div><input aria-label="Положение зоны вываживания" type="range" id="slider" min="0" max="1" step="0.001" value=".5"><div class="tension-label"><span>Натяжение лески</span><b id="tension-value">0%</b></div><div class="tension-meter"><div id="tension-bar"></div></div><div class="fight-meters"><div><small>До берега</small><div class="meter"><div id="progress-bar"></div></div></div><div><small>Силы рыбы</small><div class="meter stamina"><div id="stamina-bar"></div></div></div></div><button id="reel-button" class="full">Отпустить катушку</button><p class="hint">Держи рыбу в зоне. На рывках отпускай катушку, но не давай леске провиснуть.</p></div><small id="battle-status">Прогресс сохраняется на сервере</small></section>`;
$('slider').oninput=e=>position=Number(e.target.value);$('hook-button').onclick=()=>{hookRequested=true;step()};$('reel-button').onclick=()=>{reeling=!reeling;draw()};
// Функция draw: логика соответствующего элемента интерфейса.
function draw(){if(stopped)return;const fight=b.phase==='fight';$('battle-name').textContent=fight?b.fish.name:b.phase==='bite'?'Клюёт!':'Ждём поклёвку…';$('battle-meta').innerHTML=fight?`${rarity(b.fish)} <span class="badge">${b.kg} кг · ${esc(b.fish.behavior_name)}</span>`:'';$('battle-cue').textContent=b.cue;$('hook-button').hidden=b.phase!=='bite';$('fight-controls').hidden=!fight;$('battle-float').innerHTML=fight?itemArt(b.fish,'battle-art'):b.phase==='bite'?'❗':'🎣';$('battle-water')?.classList.toggle('rush',String(b.cue).includes('Рывок'));document.querySelectorAll('.phase-steps span').forEach(e=>e.classList.remove('active'));$('step-'+b.phase)?.classList.add('active');if(fight){$('tension-value').textContent=Math.round(b.tension*100)+'%';$('tension-bar').style.width=Math.min(100,b.tension*100)+'%';$('tension-bar').style.background=b.tension>.8?'#ff6b7d':b.tension<.1?'#78bcff':'#70d9ab';$('progress-bar').style.width=b.progress+'%';$('stamina-bar').style.width=b.stamina+'%';$('reel-button').textContent=reeling?'Отпустить катушку':'Тянуть к берегу';$('reel-button').classList.toggle('ghost',!reeling);}}
let received=performance.now();function frame(){if(stopped)return;const t=b.fight_time+Math.min(.35,(performance.now()-received)/1000),speed=b.speed*(b.stamina<20?.65:1),seed=b.seed,behavior=b.fish.behavior;let x;if(behavior==='dart')x=.5+.28*Math.sin(t*speed+seed)+.15*Math.sin(t*speed*3.7+seed);else if(behavior==='bottom')x=.65+.2*Math.sin(t*speed*.7+seed);else if(behavior==='school')x=.5+.30*Math.sin(t*speed*.8+seed);else if(behavior==='predator')x=.5+.25*Math.sin(t*speed+seed)+.15*Math.sin(t*speed*2.2);else x=.5+.27*Math.sin(t*speed*.65+seed);$('marker').style.left=Math.max(.06,Math.min(.94,x))*100+'%';$('zone').style.left=(position-b.width/2)*100+'%';$('zone').style.width=b.width*100+'%';raf=requestAnimationFrame(frame)}
// Функция step: логика соответствующего элемента интерфейса.
async function step(){if(stopped||inFlight)return;inFlight=true;const sentHook=hookRequested;try{const r=await api('/api/fishing/tick',{id:b.id,position,sequence:++sequence,reeling,hook:sentHook});if(stopped)return;if(sentHook)hookRequested=false;b=r.battle;battle=b;received=performance.now();if(r.done){stopped=true;clearInterval(timer);cancelAnimationFrame(raf);battle=null;m.hidden=true;accept(r.state);paint();note(r.won?`${b.fish.name} · ${b.kg} кг · +${b.xp} EXP`:`${b.reason}. Потеряны: ${(b.lost||[]).join(', ')||'леска и приманка'}`,r.won?b.fish.rarity:'error',r.won?'Отличный улов!':'Рыба сорвалась');if(b.find)note(b.find.name,b.find.rarity,'Находка');}else{draw();$('battle-status').textContent=b.phase==='bite'?`Окно подсечки: ${Math.max(0,b.hook_window-b.phase_time).toFixed(1)} с`:'Прогресс сохранён · леска и приманка рискуют при срыве';}}catch(e){if(!stopped)$('battle-status').textContent=e.message+' · ловля приостановлена';}finally{inFlight=false}}
const timer=setInterval(step,250);$('pause-battle').onclick=()=>{stopped=true;clearInterval(timer);cancelAnimationFrame(raf);battle=null;m.hidden=true;run(async()=>{accept(await api('/api/fishing/state'));paint();note('Заброс сохранён. Продолжишь с того же места.','info')})};draw();frame();step();}
// Функция adminView: логика соответствующего элемента интерфейса.
function adminView(){$('view').innerHTML=Admin.view();}
let authKnown=false;
const bootStarted=Date.now();
// Функция boot: логика соответствующего элемента интерфейса.
async function boot(){try{const status=await api('/api/system/status');admin=status.is_admin;authKnown=true;if(status.enabled&&!admin){$('maintenanceScreen').hidden=false;$('maintenanceMessage').textContent=status.message;$('boot').hidden=true;return;}accept(await api('/api/fishing/state'));paint();setTimeout(()=>{$('boot').classList.add('off');setTimeout(()=>$('boot').hidden=true,650);if(S.active)startBattle(S.active)},Math.max(0,1700-(Date.now()-bootStarted)))}catch(e){$('boot-msg').innerHTML=`<span>${esc(e.message)}</span><br><button class="ghost sm" style="margin-top:12px" onclick="boot()">Повторить подключение</button>`}}
let heartbeatBusy=false;
setInterval(async()=>{if(heartbeatBusy||!authKnown||battle)return;heartbeatBusy=true;try{const status=await api('/api/system/status'),blocked=status.enabled&&!status.is_admin;if(S&&!blocked){const buff=await api('/api/fishing/luck');if(buff.multiplier!==S.buff?.multiplier||buff.expires_at!==S.buff?.expires_at){accept(await api('/api/fishing/state'));if(tab!=='profile')paint();else if($('profile-luck'))$('profile-luck').innerHTML=luckView();}}const screen=$('maintenanceScreen');screen.hidden=!blocked;if(blocked){$('maintenanceMessage').textContent=status.message;}else if(!S){await boot();}else if(screen.dataset.wasBlocked==='true'){accept(await api('/api/fishing/state'));paint();}screen.dataset.wasBlocked=String(blocked);}catch(_){}finally{heartbeatBusy=false}},10000);
boot();

// Функция rewardTime: логика соответствующего элемента интерфейса.
function rewardTime(ts){const secs=Math.max(0,Math.ceil(ts-(Date.now()+offset)/1000));return `${Math.floor(secs/3600)?Math.floor(secs/3600)+':':''}${String(Math.floor(secs/60)%60).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;}
// Функция rewardsView: логика соответствующего элемента интерфейса.
function rewardsView(){const r=S.rewards||{};$('view').innerHTML=`<div class="section-heading"><div><div class="brand">ВОЗВРАЩАЙСЯ НА БЕРЕГ</div><h1>Твои награды</h1></div><span class="bag-emblem">🎁</span></div><section class="panel reward-panel"><div class="reward-emoji">⏱️</div><h2>Каждый час</h2><p><b>$100</b> и 10 EXP</p><button class="full" data-reward="hourly" onclick="claimReward('hourly')">Забрать</button><small>Раз в 60 минут с момента получения</small></section><section class="panel reward-panel"><div class="reward-emoji">🌅</div><h2>Каждый день</h2><p><b>$500–$1 100</b> · 50 EXP · береговой кейс</p><div class="streak-days">${Array.from({length:7},(_,i)=>`<span class="${i<(r.streak||0)?'done':''}">${i+1}</span>`).join('')}</div><p class="m">Серия до 7 дней. Каждый следующий день +$100. После перерыва в 48 часов серия начинается заново.</p><button class="full" data-reward="daily" onclick="claimReward('daily')">Забрать</button></section>`;updateRewardButtons();}
// Функция updateRewardButtons: логика соответствующего элемента интерфейса.
function updateRewardButtons(){if(!S)return;document.querySelectorAll('[data-reward]').forEach(button=>{const kind=button.dataset.reward,last=S.rewards?.[kind+'_at']||0,until=last+(kind==='daily'?86400:3600),left=until-(Date.now()+offset)/1000;button.disabled=left>0;button.textContent=left>0?'Через '+rewardTime(until):'Забрать награду'});}
setInterval(updateRewardButtons,1000);
// Функция claimReward: логика соответствующего элемента интерфейса.
async function claimReward(kind){if(lock)return;lock=true;try{const r=await api('/api/community/rewards/claim',{kind});accept(r.state);paint();note(`+$${fmt(r.coins)} · +${r.xp} EXP${r.case?' · береговой кейс':''}`,'success','Награда получена')}catch(e){note(e.message,'error')}finally{lock=false}}
let chatMessages=[],chatLoading=false,chatSending=false;
// Функция chatView: логика соответствующего элемента интерфейса.
function chatView(){$('view').innerHTML=`<div class="section-heading"><div><div class="brand">VIVA · РЫБАЦКОЕ СООБЩЕСТВО</div><h1>Общий чат</h1></div><span class="tag">Обновление 3 с</span></div><p class="m">Делись уловами и советами. Сообщение до 300 символов, интервал 5 секунд.</p><div id="chat-messages" class="chat-messages" aria-live="polite"></div><form class="chat-composer" onsubmit="event.preventDefault();sendChat()"><textarea id="chat-text" maxlength="300" rows="2" placeholder="Написать рыбакам…" aria-label="Текст сообщения"></textarea><button id="chat-send" type="submit">Отправить</button></form>`;drawChat();}
// Функция drawChat: логика соответствующего элемента интерфейса.
function drawChat(){const box=$('chat-messages');if(!box)return;const near=box.scrollHeight-box.scrollTop-box.clientHeight<90;box.innerHTML=chatMessages.length?chatMessages.map(m=>`<article class="chat-message ${m.telegram_id===S.player.telegram_id?'mine':''}"><div class="chat-avatar">${esc(m.avatar==='🏠'?'🎣':m.avatar)}</div><div class="chat-bubble"><div class="row"><b>${esc(m.nickname||m.telegram_name)}</b><time>${new Date(m.created_at*1000).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time>${admin&&!m.deleted?`<button class="ghost sm" onclick="deleteChat(${m.id})" aria-label="Удалить сообщение">×</button>`:''}</div><p>${m.deleted?'<i>Сообщение удалено модератором</i>':esc(m.text)}</p></div></article>`).join(''):'<div class="empty-state"><span>💬</span><h3>Первый разговор на берегу</h3><p>Поздоровайся с другими рыбаками.</p></div>';if(near)box.scrollTop=box.scrollHeight;}
// Загружает сообщения общего чата.
async function loadChat(){if(chatLoading||tab!=='chat'||document.hidden)return;chatLoading=true;try{const r=await api('/api/community/chat');if(JSON.stringify(r.messages)!==JSON.stringify(chatMessages)){chatMessages=r.messages;drawChat();}}catch(e){if(!chatMessages.length)note(e.message,'error')}finally{chatLoading=false}}
setInterval(loadChat,3000);
// Отправляет сообщение в общий чат.
async function sendChat(){const input=$('chat-text'),text=input?.value.trim();if(!text||chatSending)return;chatSending=true;$('chat-send').disabled=true;try{await api('/api/community/chat',{text});if(input)input.value='';await loadChat();const box=$('chat-messages');if(box)box.scrollTop=box.scrollHeight;}catch(e){note(e.message,'error')}finally{chatSending=false;if($('chat-send'))$('chat-send').disabled=false;}}
// Функция deleteChat: логика соответствующего элемента интерфейса.
async function deleteChat(id){if(!confirm('Удалить это сообщение?'))return;await run(async()=>{await api('/api/community/chat/delete',{id});await loadChat()});}

