'use strict';
Object.assign(noticeColors,{common:'#c5c9d0',rare:'#4d9dff',epic:'#b37aff',professional:'#ff9235',legendary:'#ffe372',mythic:'#ff5267',secret:'#ffffff',unique:'#62ed96',moderator:'#ffaf57'});
for(const k of ['line','spoon','spinner'])delete labels[k];
const glyphs={fish:'<path d="M3 12c4-7 12-7 16 0-4 7-12 7-16 0Zm16 0 3-5v10Z"/><circle cx="8" cy="11" r=".8"/>',bag:'<rect x="5" y="6" width="14" height="16" rx="4"/><path d="M9 6V3h6v3M5 13h14m-9 0v3h4v-3"/>',shop:'<path d="m3 7 9-4 9 4-9 5ZM3 7v11l9 4 9-4V7M12 12v10"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',rod:'<path d="M4 21 15 4q4-4 5 1v10q0 4-4 4m-1-15-2 17"/>',reel:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="3"/><path d="m17 17 4 4M12 2v3"/>',bait:'<path d="M12 2v11a5 5 0 0 1-10 0v-3l4 3M12 4q10 0 9 8-5 6-9 0"/>'};
// Функция ico: логика соответствующего элемента интерфейса.
function ico(k){return `<svg class="v-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${glyphs[k]||glyphs.fish}</svg>`}
const oldArt=itemArt;itemArt=function(item,extra=''){return item.art?oldArt(item,extra):`<span class="gear-illustration ${extra}">${ico(item.type||'fish')}</span>`};
const oldNote=note;note=function(text,kind='info',title=''){oldNote(text,kind,title);$('toast').firstElementChild?.classList.add('rarity-'+kind)};
const oldPaint=paint;paint=function(){oldPaint();if(!S)return;const tabs=[['fish','Рыбалка'],['bag','Рюкзак'],['shop','Кейсы']];$('nav').innerHTML=tabs.map(([k,n])=>`<button class="${tab===k?'active':''}" onclick="go('${k}')">${ico(k)}${n}</button>`).join('');$('header').insertAdjacentHTML('beforeend',`<button class="menu-button ghost" aria-label="Меню" onclick="go('menu')">${ico('menu')}</button>`);const n=$('header').querySelector('.name');if(S.profile?.prefix)n.insertAdjacentHTML('afterend',`<small class="prefix">${esc(S.profile.prefix)}</small>`);document.body.style.setProperty('--profile',S.profile?.color||'#4aaeca');if(tab==='menu')menuView();if(tab==='promo')promoView();if(tab==='top')topView();if(tab==='help')helpView();if(tab==='donate')$('view').innerHTML='<section class="panel empty-state"><h1>Магазин доната</h1><p>Технические работы</p><small>Скоро здесь появятся новые возможности.</small></section>';if(tab==='staff')staffView();};
const oldGo=go;go=function(t){oldGo(t);if(t==='top')loadTop();if(t==='staff')loadStaff()};
// Показывает главное меню и дополнительные разделы.
function menuView(){$('view').innerHTML=`<div class="brand">VIVA · ТВОЙ КЛУБ</div><h1>Меню</h1><div class="menu-grid">${[['profile','Мой профиль','Образ, статистика и коллекция'],['rewards','Награды','Ежедневные и ежечасные'],['promo','Промокоды','Забрать подарок'],['chat','Общий чат','Рыбаки со всего мира'],['top','Топ игроков','Уровень, деньги и трофеи'],['help','Помощь','Правила и информация о кейсах'],['donate','Донат','Технические работы'],...(S.role==='admin'?[['admin','Администратор','Полная панель управления']]:[]),...(S.role!=='player'?[['staff','Игроки и модерация','Паспорта, блокировки и роли']]:[])].map(([key,name,sub])=>`<button class="panel menu-entry" onclick="go('${key}')"><b>${name}</b><small>${sub}</small><span>↗</span></button>`).join('')}</div><a class="support-link" href="https://t.me/OKEY_VE" target="_blank" rel="noopener">Техническая поддержка ↗</a>`;}
// Функция scene11: логика соответствующего элемента интерфейса.
function scene11(l,small=false){return `<div class="landscape loc-${l.key} ${small?'small':''}" style="--lake-color:${l.color}"><svg viewBox="0 0 600 340" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="sky-${l.key}" x2="0" y2="1"><stop stop-color="${l.key==='stream'?'#342d68':'#244759'}"/><stop offset="1" stop-color="${l.color}"/></linearGradient></defs><rect width="600" height="340" fill="url(#sky-${l.key})"/><circle cx="440" cy="70" r="29" fill="#fff2c9" opacity=".85"/><path d="m0 200 100-95 70 58 90-113 100 118 90-58 150 110v120H0Z" fill="#172e3b"/><path d="m0 210 130-40 160 45 180-56 130 55v126H0Z" fill="#254d50"/><path d="M0 224Q170 195 320 225T600 220V340H0Z" fill="${l.color}"/><path d="M80 260h150m100 24h170m-310 23h150m30-63h60" stroke="#ffffff" stroke-width="2" opacity=".24"/><path d="M0 278q80-18 160 62H0Z" fill="#152d2c"/><g fill="#182e32">${[25,70,120,530,575].map((x,i)=>`<path d="m${x} ${170+i*4} -22 40h44Zm0 17-30 45h60Z"/><rect x="${x-3}" y="210" width="6" height="33"/>`).join('')}</g></svg><div class="landscape-title"><small>VIVA · ${l.subtitle}</small><h2>${l.name}</h2><span>Уровень ${l.level} · от ${l.required_kg} кг</span></div></div>`;}
fishView=function(){const l=S.locations[loc];document.body.dataset.location=l.key;$('view').innerHTML=`${luckView()}<div class="section-heading"><div><span class="brand">ТИШИНА. ВОДА. ТВОЙ МОМЕНТ.</span><h1>На рыбалку</h1></div><span class="tag">${loc+1} / ${S.locations.length}</span></div><div class="scene-wrap">${scene11(l)}<button class="scene-arrow prev" onclick="move(-1)">‹</button><button class="scene-arrow next" onclick="move(1)">›</button></div><div class="location-dots">${S.locations.map((l,i)=>`<button class="${loc===i?'on':''}" aria-label="${l.name}" onclick="loc=${i};fishView()"></button>`).join('')}</div><div class="cast-panel"><p>${esc(l.description)}</p><button class="full cast-button" id="cast" onclick="action('cast',{location:S.locations[loc].key})">Поймать рыбу</button><small>Один клик — и рыбак сам вытянет твой улов</small></div><div class="attempts-banner">Попытки <b></b><small id="attempts-timer"></small></div><div class="panel row"><span>Удача экипировки</span><b>+${(S.loadout.luck*100).toFixed(1)}%</b></div><button class="ghost full" onclick="go('bag');bagTab='gear';bagView()">${ico('rod')} Изменить экипировку в рюкзаке</button><details class="panel"><summary>Рыбы и шансы локации</summary><p class="hint">Удача повышает вес редких наград в таблице вероятностей, шансы пересчитываются на сервере.</p>${(S.fish_odds[l.key]||[]).map(f=>`<div class="odds-row">${itemArt(f,'odds-art')}<span>${esc(f.name)}<br>${rarity(f)}<small>${f.min_kg}–${f.max_kg} кг</small></span><b>${chanceText(f.chance)}</b></div>`).join('')}</details>`;cooldown();};
cooldown=function(){if(!S||!$('cast'))return;const now=(Date.now()+offset)/1000,a=S.attempts,extra=a.next_at&&now>=a.next_at?1+Math.floor((now-a.next_at)/120):0,n=Math.min(5,a.remaining+extra),next=a.next_at+extra*120,l=S.locations[loc],equipment=Object.values(S.progress.equipment).map(k=>S.catalog.gear.find(g=>g.key===k)),weak=equipment.length<3||equipment.some(g=>!g||g.max_kg<l.required_kg),locked=S.level.level<l.level;document.querySelector('.attempts-banner b').textContent=n+' / 5';$('attempts-timer').textContent=n<5?'Следующая через '+rewardTime(next)+' · +1 каждые 2 минуты':'Полный запас · максимум 5';$('cast').disabled=!S.active&&(locked||weak||n===0||S.catches.length>=30);$('cast').textContent=S.active?'Продолжить вываживание':locked?'Доступно с уровня '+l.level:weak?'Нужно снаряжение от '+l.required_kg+' кг':S.catches.length>=30?'Подсак заполнен':n===0?'Восстановление попытки…':'Поймать рыбу';};
// Функция weightText: логика соответствующего элемента интерфейса.
function weightText(kg){return Number(kg).toLocaleString('ru-RU',{maximumFractionDigits:3})}
// Функция fishCard: логика соответствующего элемента интерфейса.
function fishCard(f,place='bag'){return `<article class="collect-card rarity-${f.rarity}">${rarity(f)}<h3>${esc(f.name)}</h3>${itemArt(f,'collect-art')}<div class="card-numbers"><b>${weightText(f.kg)} кг</b><strong>$${fmt(f.value)}</strong></div>${place==='tank'?`<small>+$${fmt(f.hourly)} / час</small><button class="ghost full sm" onclick="vaction('tank',{action:'remove',id:${f.id}})">В подсак</button>`:`<div class="card-actions"><button class="sm" onclick="action('sell',{fish_key:'${f.id}'})">Продать</button><button class="ghost sm" onclick="vaction('tank',{action:'add',id:${f.id}})">В аквариум</button></div>`}</article>`}
// Функция gearCard: логика соответствующего элемента интерфейса.
function gearCard(g){const equipped=Object.values(S.progress.equipment).includes(g.key);return `<article class="collect-card rarity-${g.rarity}">${rarity(g)}<h3>${esc(g.name)}</h3>${itemArt(g,'collect-art')}<div class="card-numbers"><b>${g.max_kg} кг</b><b>+${(g.luck*100).toFixed(1)}%</b><strong>$${fmt(g.sell_price)}</strong></div><small>Продажа 50% · в наличии ${g.amount||1}</small><div class="card-actions"><button class="sm" ${equipped?'disabled':''} onclick="equipFromMain('${g.key}')">${equipped?'Надето':'Надеть'}</button><button class="ghost sm" onclick="vaction('gear/sell',{key:'${g.key}'})">Продать</button></div></article>`}
bagView=function(){const tank=S.aquarium;$('view').innerHTML=`<div class="brand">КАЖДЫЙ ТРОФЕЙ — ТВОЯ ИСТОРИЯ</div><h1>Рюкзак</h1><div class="bag-tabs">${[['fish','Подсак',S.catches.length+'/30'],['gear','Экипировка',S.gear.reduce((n,g)=>n+g.amount,0)+'/36'],['tank','Аквариум',tank.fish.length+'/5']].map(([key,title,count])=>`<button class="${bagTab===key?'on':''}" onclick="bagTab='${key}';bagView()">${title}<small>${count}</small></button>`).join('')}</div>${bagTab==='gear'?`${equipmentView()}<div class="bag-tabs">${Object.entries(labels).filter(([k])=>k!=='cases').map(([k,v])=>`<button class="${category===k?'on':''}" onclick="category='${k}';bagView()">${v}</button>`).join('')}</div><div class="collection-grid">${S.gear.filter(g=>g.type===category).map(gearCard).join('')||'<p>Новые снасти ждут в кейсах.</p>'}</div>`:bagTab==='tank'?`<section class="panel tank-panel"><div class="brand">ДОХОД ОТ ТВОИХ ТРОФЕЕВ</div><h1 id="tank-balance">$0</h1><p>$${fmt(tank.rate)} / час · максимум 5 часов</p><small id="tank-time"></small><button class="full" onclick="vaction('tank',{action:'claim'})">Забрать доход</button></section><div class="collection-grid">${tank.fish.map(f=>fishCard(f,'tank')).join('')||'<p>Отправь рыбу из подсака в аквариум.</p>'}</div>`:`<div class="collection-grid">${S.catches.map(f=>fishCard(f)).join('')||'<p class="panel">Подсак пуст. Время отправиться на рыбалку.</p>'}</div>${S.catches.length?`<button class="full" onclick="action('sell',{fish_key:'all'})">Продать весь улов · $${fmt(S.catches.reduce((n,f)=>n+f.value,0))}</button>`:''}`}`;updateTank();};
// Функция updateTank: логика соответствующего элемента интерфейса.
function updateTank(){if(!$('tank-balance')||!S)return;const t=S.aquarium,now=(Date.now()+offset)/1000,delta=Math.max(0,Math.min(now,t.cap_at)-Math.min(t.server_time,t.cap_at)),value=t.balance+delta*t.rate/3600;$('tank-balance').textContent='$'+value.toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2});$('tank-time').textContent=now>=t.cap_at?'Накопление остановлено — забери доход':'До заполнения '+rewardTime(t.cap_at);}
setInterval(updateTank,250);
// Функция vaction: логика соответствующего элемента интерфейса.
async function vaction(path,body){if(lock)return;lock=true;try{const r=await api('/api/v11/'+path,body);if(r.state)accept(r.state);paint();note('Изменения сохранены','success')}catch(e){note(e.message,'error')}finally{lock=false}}
openEquipment=function(type){category=type;$('modal').hidden=false;$('modal').innerHTML=`<section class="equipment-sheet"><div class="row"><h2>${labels[type]}</h2><button class="ghost" onclick="closeModal()">×</button></div><div class="collection-grid">${S.gear.filter(g=>g.type===type).map(gearCard).join('')}</div></section>`;};
let selectedCase=null,caseCount=1,caseFast=false;
shopView=function(){if(selectedCase&&S.cases.some(c=>c.key===selectedCase))return caseView();$('view').innerHTML=`${luckView()}<div class="brand">НОВОЕ СНАРЯЖЕНИЕ. НОВЫЕ ГЛУБИНЫ.</div><h1>Кейсы</h1><p class="m">Три арсенала: удочки, катушки и приманки. Состав и шансы доступны перед открытием.</p><div class="case-grid">${S.cases.map((c,i)=>`<article class="shop-case"><div class="case-art" style="color:${['#69c8cb','#a39aff','#ffc278'][i%3]}"><div class="case-orbit"></div><span>${ico(c.type)}</span><b>VIVA · ${c.type.toUpperCase()}</b></div><div class="case-info"><h2>${esc(c.name)}</h2><p>${c.rewards.length} предметов · $${fmt(c.price)}</p><button class="full" ${!c.enabled?'disabled':''} onclick="selectedCase='${c.key}';caseView()">Посмотреть кейс ${c.amount?'· '+c.amount+' шт.':''}</button></div></article>`).join('')}</div>`;};
// Рисует страницу открытия кейса.
function caseView(){const c=S.cases.find(c=>c.key===selectedCase);$('view').innerHTML=`<button class="ghost" onclick="selectedCase=null;shopView()">‹ Все кейсы</button><div class="brand">VIVA · ${c.type.toUpperCase()}</div><h1>${esc(c.name)}</h1><section class="panel"><div class="case-art"><span>${ico(c.type)}</span></div><p>$${fmt(c.price)} за кейс · своих кейсов ${c.amount}</p><div class="bag-tabs">${[1,3,5].map(n=>`<button class="${caseCount===n?'on':''}" onclick="caseCount=${n};caseView()">×${n}</button>`).join('')}</div><label class="fast-toggle"><input type="checkbox" ${caseFast||caseCount!==1?'checked':''} ${caseCount!==1?'disabled':''} onchange="caseFast=this.checked"> ${caseCount!==1?'Быстрая анимация · награды по очереди':'Быстрое открытие'}</label><button class="full" id="case-open" onclick="open11Case()">Открыть ${caseCount} · $${fmt(Math.max(0,caseCount-c.amount)*c.price)}</button></section><div id="case-results"></div><h2>Состав и вероятности</h2><p class="hint">Если 20 мест экипировки заняты, награда продаётся за 50% рыночной цены. Все предметы имеют постоянную цену.</p><div class="collection-grid">${c.rewards.map(g=>`<div class="collect-card rarity-${g.rarity}">${rarity(g)}<h3>${esc(g.name)}</h3>${itemArt(g,'collect-art')}<strong>${chanceText(g.chance)}</strong><p>${g.max_kg} кг · +${(g.luck*100).toFixed(1)}%</p><small>Рынок $${fmt(g.price)} · продажа $${fmt(g.sell_price)}</small></div>`).join('')}</div>`;}
// Функция open11Case: логика соответствующего элемента интерфейса.
async function open11Case(){if(lock)return;lock=true;const c=S.cases.find(c=>c.key===selectedCase);$('case-open').disabled=true;try{const r=await api('/api/fishing/case/open',{case_key:c.key,revision:c.revision,count:caseCount});if(caseCount===1&&!caseFast)await roulette(c,r.rewards[0].reward);accept(r.state);paint();$('case-results').innerHTML=`<h2>Твои награды · +${35*r.rewards.length} EXP</h2><div class="collection-grid">${r.rewards.map(x=>`<article class="collect-card rarity-${x.reward.rarity}">${rarity(x.reward)}<h3>${esc(x.reward.name)}</h3>${itemArt(x.reward,'collect-art')}<p>${x.auto_sold?'Автопродажа +$'+fmt(x.compensation):'Добавлено в рюкзак'}</p></article>`).join('')}</div>`;note(r.rewards.map(x=>x.reward.name).join(', '),r.rewards[0].reward.rarity,'Кейс открыт')}catch(e){note(e.message,'error');if($('case-open'))$('case-open').disabled=false}finally{lock=false}}
// Функция roulette: логика соответствующего элемента интерфейса.
function roulette(c,winner){return new Promise(resolve=>{const list=Array.from({length:44},()=>c.rewards[Math.floor(Math.random()*c.rewards.length)]);list[36]=winner;$('modal').hidden=false;$('modal').innerHTML=`<section class="roulette-panel"><div class="brand">VIVA · ОТКРЫТИЕ КЕЙСА</div><h2>${esc(c.name)}</h2><div class="roulette-window"><div class="roulette-strip">${list.map(g=>`<div class="roulette-item rarity-${g.rarity}">${itemArt(g,'collect-art')}<small>${esc(g.name)}</small></div>`).join('')}</div><div class="roulette-needle"></div></div><button id="skip-roll" class="ghost full">Показать сразу</button></section>`;let ended=false;const done=()=>{if(ended)return;ended=true;clearTimeout(timer);$('modal').hidden=true;resolve()};const timer=setTimeout(done,4600);$('skip-roll').onclick=done;requestAnimationFrame(()=>requestAnimationFrame(()=>{const w=document.querySelector('.roulette-window').clientWidth;document.querySelector('.roulette-strip').style.transform=`translateX(${w/2-36*132-62}px)`}));});}
startBattle=function(initial){let b=initial,seq=0,inflight=false,stopped=false;battle=b;$('modal').hidden=false;const color=noticeColors[b.fish.rarity],l=S.locations.find(l=>l.key===b.fish.location)||S.locations[loc];$('modal').innerHTML=`<section class="catch-cinema rarity-${b.fish.rarity}" style="--catch-color:${color};--duration:${b.duration}s"><div class="brand">VIVA · ВЫВАЖИВАНИЕ</div><h2>${S.catalog.rarities[b.fish.rarity]}</h2><div class="cinema-stage">${scene11(l)}<svg class="angler" viewBox="0 0 300 300"><ellipse cx="135" cy="276" rx="60" ry="8" fill="#061e23" opacity=".5"/><path d="m125 200-18 68m47-68 23 68" stroke="#152a3f" stroke-width="18" stroke-linecap="round"/><path d="M114 150q25-16 49 0l3 64h-52Z" fill="#dc9c50"/><circle cx="139" cy="128" r="21" fill="#dcb591"/><path d="M112 123q3-32 28-27 23 2 26 28Z" fill="#25414b"/><path d="m117 160 50 24 29-39m-35 17 27 13 17-24" fill="none" stroke="#d49f7e" stroke-width="12" stroke-linecap="round"/><g class="pull-rod"><path d="m180 180 54-118q26-26 34 10" stroke="#d8d9ba" stroke-width="4" fill="none"/><path d="M268 72q18 100-15 158" fill="none" stroke="#e5f7ff" stroke-width="1.3"/></g></svg><div class="cinema-fish">${itemArt(b.fish,'collect-art')}</div><div class="cinema-splash"></div>${Array.from({length:8+b.tier*6},(_,i)=>`<i class="catch-particle" style="--i:${i};left:${10+(i*37)%80}%;animation-delay:${i*.09}s"></i>`).join('')}</div><p id="catch-status">Рыбак вытягивает улов…</p><div class="meter"><div id="catch-progress"></div></div><button class="ghost full" id="hide-catch">Продолжить позже</button></section>`;
const stop=()=>{stopped=true;clearInterval(timer);battle=null;$('modal').hidden=true};$('hide-catch').onclick=()=>{stop();paint()};
// Функция step: логика соответствующего элемента интерфейса.
async function step(){if(stopped||inflight)return;inflight=true;try{const r=await api('/api/fishing/tick',{id:b.id,position:.5,sequence:++seq});if(stopped)return;b=r.battle;$('catch-progress').style.width=b.progress+'%';if(r.done){stop();accept(r.state);paint();$('modal').hidden=false;$('modal').innerHTML=`<section class="reward-card rarity-${b.fish.rarity}"><div class="brand">ТВОЙ УЛОВ</div>${rarity(b.fish)}${itemArt(b.fish,'collect-art')}<h1>${esc(b.fish.name)}</h1><h2>${weightText(b.kg)} кг</h2><p>+${b.xp} EXP · рыба в подсаке</p><button class="full" onclick="closeModal()">Продолжить рыбалку</button></section>`;note(b.fish.name+' · '+b.kg+' кг',b.fish.rarity,'Рыба поймана')}}catch(e){if($('catch-status'))$('catch-status').textContent=e.message+' · повторяем соединение'}finally{inflight=false}}const timer=setInterval(step,600);step();};
const oldProfile=profileView;profileView=function(){oldProfile();$('view').insertAdjacentHTML('afterbegin',`<section class="passport" style="--passport:${S.profile.color}"><small>VIVA FISHING · ПАСПОРТ РЫБАКА</small><div class="row"><strong>${esc(S.player.avatar)}</strong><div><h2>${esc(S.player.nickname||S.player.telegram_name)}</h2><span class="prefix">${esc(S.profile.prefix)}</span></div></div><p>№ ${S.player.telegram_id} · уровень ${S.level.level}</p></section>`);$('nickname').insertAdjacentHTML('afterend',`<label>Цвет профиля <input type="color" id="profile-color" value="${esc(S.profile.color)}"></label>`);};
saveProfile=async function(){await action('profile',{nickname:$('nickname').value.trim(),avatar:selectedAvatar,color:$('profile-color').value})};
// Функция promoView: логика соответствующего элемента интерфейса.
function promoView(){$('view').innerHTML='<div class="brand">VIVA · ПОДАРКИ</div><h1>Промокоды</h1><section class="panel"><label>Твой промокод</label><input id="promo-code" maxlength="32" placeholder="Введи код"><button class="full" onclick="vaction(\'promo\',{code:$(\'promo-code\').value})">Активировать</button></section>'}
// Функция helpView: логика соответствующего элемента интерфейса.
function helpView(){$('view').innerHTML=`<div class="brand">VIVA · РУКОВОДСТВО</div><h1>Помощь</h1>${[['Ловля','Нажми «Поймать рыбу». Вываживание автоматическое, без срывов и потери экипировки. Анимация длится от 3,5 до 10 секунд в зависимости от редкости.'],['Попытки','Запас — 5. Одна попытка восстанавливается каждые 2 минуты. При полном запасе восстановление останавливается.'],['Локации','Нужен указанный уровень. Удочка, катушка и приманка должны выдерживать максимальный вес рыбы локации. Удача каждого предмета — до 15%.'],['Рюкзак','Подсак — 30 рыб, экипировка — 20 единиц. Старые вещи при обновлении сохраняются, даже если лимит превышен. Продай лишнее, чтобы освободить место.'],['Аквариум','До 5 рыб. Доход зависит от веса, стоимости и редкости. Накапливается до 5 часов после сбора; перестановка рыб не продлевает срок.'],['Кейсы','Есть отдельные кейсы удочек, катушек и приманок. Открытие ×1, ×3, ×5, ×10. Для нескольких кейсов включается короткая анимация появления наград. Дубликаты хранятся, при полном рюкзаке награда продаётся автоматически.'],['Экономика','Рыба оценивается по фактическому весу. Снасть продаётся за 50% фиксированной рыночной цены. Высшая редкость всегда дороже низшей.'],['Редкости','Обычный → Редкий → Эпический → Профессиональный → Легендарный → Мифический → Секретный. Уникальный пока недоступен.']].map(([h,p])=>`<section class="panel"><h2>${h}</h2><p>${p}</p></section>`).join('')}<a class="support-link" href="https://t.me/OKEY_VE" target="_blank" rel="noopener">Поддержка @OKEY_VE ↗</a>`;}
let topKind='level',topRows=[];
// Функция topView: логика соответствующего элемента интерфейса.
function topView(){$('view').innerHTML=`<div class="brand">VIVA · ЛУЧШИЕ НА БЕРЕГУ</div><h1>Топ игроков</h1><div class="bag-tabs">${[['level','Уровень'],['coins','Деньги'],['record','Рекорд']].map(([k,n])=>`<button class="${k===topKind?'on':''}" onclick="topKind='${k}';loadTop()">${n}</button>`).join('')}</div><div id="top-list">${topRows.map((p,i)=>`<div class="panel row"><b>#${i+1}</b><div class="grow"><b>${esc(p.prefix||'')} ${esc(p.nickname||p.telegram_name)}</b>${topKind==='record'?`<small>${esc(p.fish_name)} · ${S.catalog.rarities[p.rarity]}</small>`:''}</div><strong>${topKind==='coins'?'$'+fmt(p.coins):topKind==='record'?weightText(p.kg)+' кг':'Ур. '+p.level}</strong></div>`).join('')||'<p>Рейтинг загружается…</p>'}</div>`;}
// Функция loadTop: логика соответствующего элемента интерфейса.
async function loadTop(){await run(async()=>{const r=await api('/api/v11/top?kind='+topKind);topRows=r.players;if(tab==='top')topView()})}
let staffRows=[];
// Функция staffView: логика соответствующего элемента интерфейса.
function staffView(){$('view').innerHTML=`<div class="brand">VIVA · ${S.role==='admin'?'УПРАВЛЕНИЕ':'МОДЕРАЦИЯ'}</div><h1>Игроки</h1><form class="row" onsubmit="event.preventDefault();loadStaff()"><input id="staff-query" placeholder="Ник или ID"><button>Найти</button></form><div id="staff-list">${staffRows.map(p=>`<button class="panel staff-row full" onclick="staffCard(${p.telegram_id})"><span>${esc(p.avatar)}</span><div><b>${esc(p.nickname||p.telegram_name)}</b><small>ID ${p.telegram_id} · $${fmt(p.coins)} ${p.blocked?'· заблокирован':''}</small></div><b>↗</b></button>`).join('')}</div>${S.role==='admin'?`<section class="panel"><h2>Создать промокод</h2><input id="new-code" placeholder="Код"><label>Доллары<input id="new-coins" type="number" min="0" value="500"></label><label>EXP<input id="new-xp" type="number" min="0" value="50"></label><label>Число активаций<input id="new-uses" type="number" min="1" value="100"></label><label>Срок в часах<input id="new-hours" type="number" min="1" value="168"></label><button class="full" onclick="vaction('admin/promo',{code:$('new-code').value,coins:+$('new-coins').value,xp:+$('new-xp').value,uses:+$('new-uses').value,hours:+$('new-hours').value})">Создать</button></section>`:''}`;}
// Функция loadStaff: логика соответствующего элемента интерфейса.
async function loadStaff(){const q=$('staff-query')?.value||'';await run(async()=>{staffRows=(await api('/api/v11/players?q='+encodeURIComponent(q))).players;if(tab==='staff')staffView()})}
// Функция staffCard: логика соответствующего элемента интерфейса.
async function staffCard(uid){await run(async()=>{const p=await api('/api/v11/players/'+uid),u=p.player;$('modal').hidden=false;$('modal').innerHTML=`<section class="equipment-sheet"><div class="row"><div class="brand">ПАСПОРТ ИГРОКА</div><button class="ghost" onclick="closeModal()">×</button></div><div class="passport" style="--passport:${p.profile.color}"><small>VIVA FISHING · ID ${uid}</small><div class="row"><strong>${esc(u.avatar)}</strong><h2>${esc(u.nickname||u.telegram_name)}</h2></div><span class="prefix">${esc(p.profile.prefix)}</span><p>Уровень ${p.level.level} · $${fmt(u.coins)}</p><p>Уловов ${p.progress.catches} · рекорд ${p.best_kg} кг</p><p>Подсак ${p.catches.length}/30 · аквариум ${p.aquarium.fish.length}/5</p></div><h2>Управление игроком</h2><label>Причина<input id="block-reason" maxlength="300" value="${esc(u.reason||'')}"></label><button class="full" onclick="staffBlock(${uid},${!u.blocked})">${u.blocked?'Разблокировать':'Заблокировать'}</button>${S.role==='admin'?`<hr><label>Префикс<select id="staff-prefix"><option value="">Без префикса</option>${S.prefixes.map(x=>`<option ${x===p.profile.prefix?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="fast-toggle"><input type="checkbox" id="staff-moderator" ${p.profile.moderator?'checked':''}> Модератор: просмотр и блокировки</label><button class="full" onclick="saveStaff(${uid})">Сохранить роль и префикс</button><button class="ghost full" onclick="closeModal();go('admin');Admin.open(${uid})">Открыть полную админку</button>`:''}</section>`})}
// Функция staffBlock: логика соответствующего элемента интерфейса.
async function staffBlock(uid,blocked){await run(async()=>{await api('/api/v11/players/'+uid+'/block',{blocked,reason:$('block-reason').value});note('Статус игрока обновлён','moderator');await staffCard(uid);loadStaff()})}
// Функция saveStaff: логика соответствующего элемента интерфейса.
async function saveStaff(uid){await run(async()=>{await api('/api/v11/admin/staff',{uid,prefix:$('staff-prefix').value,moderator:$('staff-moderator').checked});note('Роль и префикс сохранены','moderator');await staffCard(uid)})}
// Show persisted administrator changes once per browser session.
const noticeSeen=new Set();const priorAccept=accept;accept=function(state){priorAccept(state);for(const n of state.notices||[]){if(!noticeSeen.has(n.id)){noticeSeen.add(n.id);note(n.text,n.kind,'Изменение профиля')}}};
let statePollBusy=false;
setInterval(async()=>{if(!S||battle||lock||document.hidden||statePollBusy)return;statePollBusy=true;try{const r=await api('/api/fishing/state');accept(r);const wallet=$('header').querySelector('.wallet');if(wallet)wallet.textContent='$ '+fmt(S.player.coins)}catch(_){}finally{statePollBusy=false}},15000);

// ===== layer: v12.js =====
'use strict';
// V12: specimen images are shown exclusively inside fish cards.
const artBeforeV12=itemArt;
itemArt=function(item,extra=''){
  if(item.location&&item.art?.atlas?.startsWith('fish12_')){
    if(!extra.split(' ').includes('collect-art'))return `<span class="fish-list-symbol" aria-hidden="true">${ico('fish')}</span>`;
    const a=item.art,[x,y,w,h]=a.rect,[sw,sh]=a.size;
    return `<span class="fish-photo-frame ${extra}" role="img" aria-label="${esc(item.name)}"><span class="fish-photo" style="background-image:url('/assets/${a.atlas}.webp');background-size:${sw/w*100}% ${sh/h*100}%;background-position:${x/(sw-w)*100}% ${y/(sh-h)*100}%"></span></span>`;
  }
  return artBeforeV12(item,extra);
};
const visualRandom=()=>{if(globalThis.crypto?.getRandomValues){const x=new Uint32Array(1);crypto.getRandomValues(x);return x[0]/4294967296}return Math.random()};
roulette=function(c,winner){return new Promise(resolve=>{
  const winnerIndex=52+Math.floor(visualRandom()*5),landing=.045+visualRandom()*.91,duration=7800+visualRandom()*600;
  const list=Array.from({length:64},()=>c.rewards[Math.floor(visualRandom()*c.rewards.length)]);list[winnerIndex]=winner;
  const m=$('modal');m.hidden=false;m.innerHTML=`<section class="premium-roll" role="dialog" aria-modal="true" aria-label="Открытие кейса"><div class="roll-overline">VIVA · CASE COLLECTION</div><h1>${esc(c.name)}</h1><p class="roll-caption" id="roll-caption">Сейчас решится…</p><div class="roulette-window premium-roll-window"><div class="roulette-strip premium-roll-strip">${list.map((g,i)=>`<article class="roulette-item premium-roll-item rarity-${g.rarity}" data-roll-index="${i}"><span class="roll-rarity-line"></span>${itemArt(g,'collect-art')}<small>${esc(g.name)}</small><span class="roll-item-rarity">${esc(S.catalog.rarities[g.rarity])}</span></article>`).join('')}</div><div class="roll-shade left"></div><div class="roll-shade right"></div><div class="roulette-needle premium-roll-needle"><i></i></div></div><div class="roll-footer"><span class="roll-status"><i></i><b id="roll-stage">Рулетка запущена</b></span><button class="ghost" id="skip-roll">Пропустить анимацию</button></div></section>`;
  const strip=m.querySelector('.premium-roll-strip'),viewport=m.querySelector('.premium-roll-window'),cards=[...strip.children],winning=cards[winnerIndex];let ended=false,finishing=false,animation=null,raf=0,timer=0,lastIndex=-1,lastHaptic=0;
  const target=()=>viewport.clientWidth/2-winning.offsetLeft-winning.offsetWidth*landing;
  const finish=(quick=false)=>{if(ended||finishing)return;finishing=true;cancelAnimationFrame(raf);clearTimeout(timer);animation?.cancel();strip.style.transform=`translateX(${target()}px)`;cards.forEach(c=>c.classList.remove('under-needle'));winning.classList.add('roll-winner');$('roll-stage').textContent='Твой предмет';$('roll-caption').textContent=winner.name;tg?.HapticFeedback?.notificationOccurred?.('success');setTimeout(()=>{if(ended)return;ended=true;m.hidden=true;resolve()},quick?180:750)};
  $('skip-roll').onclick=()=>finish(true);
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    if(finishing)return;
    const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
    const span=reduced?250:duration;
    strip.style.transform='translateX(0px)';animation=strip.animate([{transform:'translateX(0px)'},{transform:`translateX(${target()}px)`}],{duration:span,easing:'cubic-bezier(.10,.72,.12,1)',fill:'forwards'});
    const start=performance.now();
    const frame=()=>{if(finishing||ended)return;const now=performance.now(),p=Math.min(1,(now-start)/span),matrix=new DOMMatrixReadOnly(getComputedStyle(strip).transform),needle=viewport.clientWidth/2-matrix.m41,pitch=cards[1].offsetLeft-cards[0].offsetLeft,index=Math.max(0,Math.min(cards.length-1,Math.floor(needle/pitch)));
      if(index!==lastIndex){cards[lastIndex]?.classList.remove('under-needle');cards[index]?.classList.add('under-needle');lastIndex=index;if(now-lastHaptic>110){tg?.HapticFeedback?.impactOccurred?.('light');lastHaptic=now}}
      $('roll-stage').textContent=p<.35?'Разгон':p<.75?'Рулетка замедляется':'Ещё мгновение…';raf=requestAnimationFrame(frame)};
    frame();animation.finished.then(()=>finish()).catch(()=>{});timer=setTimeout(()=>finish(),span+300);
  }));
});};

