'use strict';
// A new administration interface. All permissions remain enforced by the server.
window.Admin=(()=>{
 const A={sub:'overview',loading:false,busy:false,error:'',data:{},q:'',filter:'all',sort:'last_seen',page:0,card:null,cardTab:'passport',caseKey:null,revision:0,confirm:null};
 const names={overview:'Обзор',players:'Игроки',cases:'Кейсы',promos:'Промокоды',roles:'Модераторы',system:'Сервер',messages:'Сообщения',log:'Журнал'};
 const paths={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',players:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8m9 0a4 4 0 0 1 0 8',cases:'m3 7 9-4 9 4-9 5ZM3 7v11l9 4 9-4V7m-9 5v10',promos:'M3 6h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4Zm9 0v2m0 3v2m0 3v2',roles:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Zm-4 10 3 3 5-6',system:'M3 3h18v7H3zm0 11h18v7H3zM7 6h.01M7 17h.01',messages:'M21 11a9 9 0 0 1-9 9H4l-2 2v-8a9 9 0 1 1 19-3ZM7 10h10M7 14h6',log:'M6 3h12v18H6zM9 7h6M9 11h6M9 15h4',refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 3M4 16l2 3a7 7 0 0 0 12-2',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',arrow:'m9 5 7 7-7 7',close:'m6 6 12 12M18 6 6 18',check:'m5 12 4 4L19 6',money:'M3 5h18v14H3zM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',copy:'M8 8h13v13H8zM16 8V3H3v13h5',fish:'M3 12c4-7 12-7 16 0-4 7-12 7-16 0m16 0 3-5v10Z'};
 const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.overview}"/></svg>`;
 const isAdmin=()=>S?.role==='admin';
 const date=t=>t?new Date(t*1000).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
 const ago=t=>!t?'Не был в игре':Date.now()/1000-t<90?'Сейчас в игре':date(t);
 const btn=(text,handler,kind='',disabled=false)=>`<button class="ac-btn ${kind}" onclick="${handler}" ${disabled?'disabled':''}>${text}</button>`;
 const hint=t=>`<p class="ac-hint">${t}</p>`;
 const box=(title,content,extra='')=>`<section class="ac-box ${extra}"><div class="ac-box-heading"><h2>${title}</h2></div>${content}</section>`;
 function render(){if(tab==='admin')paint()}
 const busy=async fn=>{if(A.busy)return;A.busy=true;document.querySelectorAll('[data-ac-submit]').forEach(e=>e.disabled=true);try{await fn()}catch(e){note(e.message,'error')}finally{A.busy=false;document.querySelectorAll('[data-ac-submit]').forEach(e=>e.disabled=false)}};
 function loading(){return '<div class="ac-loading"><div class="spin"></div><p>Загружаем данные…</p></div>'}
 function playerRow(p){return `<button class="ac-player-row" onclick="Admin.open(${p.telegram_id})"><span class="ac-avatar">${esc(p.avatar==='🏠'?'🎣':p.avatar||'🎣')}</span><span class="ac-person"><b>${esc(p.nickname||p.telegram_name)}</b><small>ID ${p.telegram_id}${p.level?' · ур. '+p.level:''} · ${p.blocked?'заблокирован':ago(p.last_seen)}</small></span><span class="ac-row-wallet">$${fmt(p.coins)}</span>${icon('arrow')}</button>`}
 async function load(){const rev=++A.revision,key=A.sub;A.loading=true;A.error='';render();try{
  if(!isAdmin()){if(key!=='players')A.sub='players';const r=await api('/api/v11/players?q='+encodeURIComponent(A.q));if(rev===A.revision)A.data.players={players:r.players,total:r.players.length};}
  else if(key==='overview'){const [stats,live]=await Promise.all([api('/api/admin/stats'),api('/api/admin/live')]);if(rev===A.revision){A.data.stats=stats;A.data.live=live;}}
  else if(key==='players'){const r=await api(`/api/admin/players?q=${encodeURIComponent(A.q)}&flt=${A.filter}&sort=${A.sort}&offset=${A.page*25}&limit=25`);if(rev===A.revision)A.data.players=r;}
  else if(key==='cases'){const r=await api('/api/admin/cases');if(rev===A.revision)A.data.cases=r;}
  else if(key==='promos'){const r=await api('/api/v11/admin/promos');if(rev===A.revision)A.data.promos=r.promos;}
  else if(key==='roles'){const r=await api('/api/v11/admin/moderators');if(rev===A.revision)A.data.roles=r.players;}
  else if(key==='system'){const [stats,maint]=await Promise.all([api('/api/admin/stats'),api('/api/admin/maintenance')]);if(rev===A.revision){A.data.stats=stats;A.data.maint=maint;}}
  else if(key==='messages'){const r=await api('/api/admin/broadcast');if(rev===A.revision)A.data.broadcast=r;}
  else if(key==='log'){const r=await api('/api/admin/log?limit=100');if(rev===A.revision)A.data.log=r.log;}
 }catch(e){if(rev===A.revision)A.error=e.message}finally{if(rev===A.revision){A.loading=false;render()}}}
 function setSub(key){if(!isAdmin()&&key!=='players')return;A.sub=key;A.caseKey=null;load()}
 function overview(){const s=A.data.stats?.stats||{},l=A.data.live||{};const metrics=[['players','Игроков',fmt(s.players),'Все рыбаки клуба'],['roles','Сейчас онлайн',fmt(l.count),'Активность за 75 секунд'],['money','Деньги в игре','$'+fmt(s.coins_total),'Баланс игроков'],['fish','Поймано рыб',fmt(s.fishing_catches),'За всё время']];return `<div class="ac-welcome"><div><span class="ac-eyebrow">VIVA CONTROL</span><h1>Всё под контролем.</h1><p>Игроки, экономика и состояние клуба — в одном месте.</p></div><span class="ac-health"><i></i> ${A.data.stats?.maintenance?.enabled?'Технические работы':'Игра работает'}</span></div><div class="ac-metrics">${metrics.map(([i,n,v,s])=>`<article><span>${icon(i)}${n}</span><strong>${v}</strong><small>${s}</small></article>`).join('')}</div><div class="ac-quick">${[['players','Найти игрока','Баланс, инвентарь и блокировки'],['cases','Настроить кейсы','Состав, цена и вероятности'],['promos','Создать промокод','Подарки для сообщества'],['system','Управление сервером','Доступ и диагностика']].map(([k,n,s])=>`<button onclick="Admin.setSub('${k}')">${icon(k)}<b>${n}</b><small>${s}</small>${icon('arrow')}</button>`).join('')}</div><div class="ac-two">${box('На берегу сейчас',l.online?.length?l.online.slice(0,7).map(playerRow).join(''):'<div class="ac-empty">Сейчас игроков онлайн нет.</div>')}${box('Сегодня в клубе',`<div class="ac-facts"><div><span>Новые игроки за сутки</span><b>${fmt(s.new_24h)}</b></div><div><span>Активные за сутки</span><b>${fmt(s.active_24h)}</b></div><div><span>Открыто кейсов</span><b>${fmt(s.cases_opened)}</b></div><div><span>Заблокировано</span><b>${fmt(s.blocked)}</b></div><div><span>Отклик базы</span><b>${A.data.stats?.db_ms||0} мс</b></div></div>`)}</div>`}
 function players(){const L=A.data.players||{players:[],total:0};return `<div class="ac-page-title"><div><span class="ac-eyebrow">СООБЩЕСТВО</span><h1>Игроки <small>${fmt(L.total)}</small></h1></div></div><form class="ac-search" onsubmit="event.preventDefault();Admin.search()">${icon('search')}<input id="ac-search" placeholder="Имя, ник или Telegram ID" value="${esc(A.q)}"><button class="ac-btn">Найти</button></form>${isAdmin()?`<div class="ac-filter-row"><div class="ac-chips">${[['all','Все'],['live','Онлайн'],['blocked','Блокировки'],['new','Новые']].map(([k,n])=>`<button class="${A.filter===k?'selected':''}" onclick="Admin.filter('${k}')">${n}</button>`).join('')}</div><select aria-label="Сортировка" onchange="Admin.sort(this.value)">${[['last_seen','По активности'],['coins','По деньгам'],['xp','По уровню'],['catches','По уловам']].map(([k,n])=>`<option value="${k}" ${A.sort===k?'selected':''}>${n}</option>`).join('')}</select></div>`:hint('Модератору доступны просмотр игроков и блокировка / разблокировка.')}<section class="ac-box ac-player-list">${L.players.map(playerRow).join('')||'<div class="ac-empty">По запросу никого не нашли.</div>'}</section>${isAdmin()?`<div class="ac-pagination">${btn('← Назад','Admin.page(-1)','ghost',A.page===0)}<span>${L.total?A.page*25+1:0}–${Math.min(L.total,(A.page+1)*25)} из ${L.total}</span>${btn('Далее →','Admin.page(1)','ghost',(A.page+1)*25>=L.total)}</div>`:''}`}
 function cases(){const D=A.data.cases;if(!D)return loading();const c=D.cases.find(x=>x.key===A.caseKey);if(!c)return `<div class="ac-page-title"><div><span class="ac-eyebrow">ЭКОНОМИКА</span><h1>Кейсы</h1></div></div><div class="ac-case-grid">${D.cases.map(c=>`<button class="ac-case" onclick="Admin.editCase('${c.key}')"><span class="ac-case-icon">${ico(c.type)}</span><span class="ac-badge ${c.enabled?'':'off'}">${c.enabled?'В продаже':'Закрыт'}</span><h2>${esc(c.name)}</h2><p>$${fmt(c.price)} <small>· ${c.items.length} предметов</small></p><span class="ac-case-link">Настроить ${icon('arrow')}</span></button>`).join('')}</div>`;
  const ws=Object.fromEntries(c.items.map((k,i)=>[k,c.weights[i]]));return `${btn('← Все кейсы',"Admin.editCase(null)",'ghost')}<div class="ac-page-title"><div><span class="ac-eyebrow">НАСТРОЙКА АРСЕНАЛА</span><h1>${esc(c.name)}</h1></div></div><section class="ac-box"><div class="ac-form-grid"><label>Цена кейса, $<input id="ac-case-price" type="number" min="0" max="1000000000" value="${c.price}"></label><label>Доступность<select id="ac-case-enabled"><option value="true" ${c.enabled?'selected':''}>В продаже</option><option value="false" ${!c.enabled?'selected':''}>Закрыт</option></select></label></div>${hint('Вес задаёт относительную частоту выпадения. Нулевой вес исключает предмет из кейса.')}</section><section class="ac-box">${Object.entries(S.catalog.rarities).filter(([r])=>r!=='unique').map(([r,n])=>`<details class="ac-rarity-group"><summary><i style="background:${noticeColors[r]}"></i><b>${esc(n)}</b><small>${D.gear.filter(g=>g.rarity===r&&g.type===c.type).length} предметов</small></summary>${D.gear.filter(g=>g.rarity===r&&g.type===c.type).map(g=>`<div class="ac-weight-row"><span><b>${esc(g.name)}</b><small>Продажа $${fmt(g.sell_price)}</small></span><label>Вес<input type="number" min="0" step="any" max="1000000" data-ac-weight="${g.key}" value="${ws[g.key]||0}" oninput="Admin.chances()"></label><strong data-ac-chance="${g.key}">${chanceText((ws[g.key]||0)/c.weights.reduce((a,b)=>a+b,0)*100)}</strong></div>`).join('')}</details>`).join('')}</section><div class="ac-save-bar"><span id="ac-case-total">Все изменения сохранятся вместе</span><button class="ac-btn" data-ac-submit onclick="Admin.saveCase()">${icon('check')} Сохранить состав</button></div>`;
 }
 function promos(){return `<div class="ac-page-title"><div><span class="ac-eyebrow">ПОДАРКИ ДЛЯ СООБЩЕСТВА</span><h1>Промокоды</h1></div></div>${box('Новый промокод',`<form onsubmit="event.preventDefault();Admin.createPromo()"><div class="ac-form-grid"><label class="wide">Код<input id="ac-promo-code" required minlength="2" maxlength="32" pattern="[A-Za-z0-9_-]{2,32}" placeholder="Например VIVA2026"></label><label>Доллары<input id="ac-promo-coins" type="number" min="0" max="1000000000" value="500" required></label><label>Опыт, EXP<input id="ac-promo-xp" type="number" min="0" max="10000000" value="50" required></label><label>Число активаций<input id="ac-promo-uses" type="number" min="1" max="1000000" value="100" required></label><label>Срок, часов<input id="ac-promo-hours" type="number" min="1" max="8760" value="168" required></label></div><button class="ac-btn" data-ac-submit>${icon('promos')} Создать промокод</button></form>`)}<h2 class="ac-section-title">Созданные коды</h2><div class="ac-promo-list">${(A.data.promos||[]).map(p=>`<article class="ac-box ac-promo"><div><b>${esc(p.code)}</b><span class="ac-badge ${p.uses>0&&p.expires>Date.now()/1000?'':'off'}">${p.uses>0&&p.expires>Date.now()/1000?'Активен':'Завершён'}</span></div><p>$${fmt(p.coins)} · ${fmt(p.xp)} EXP</p><small>Осталось ${fmt(p.uses)} активаций · до ${date(p.expires)}</small></article>`).join('')||'<div class="ac-empty">Пока промокодов нет.</div>'}</div>`}
 function roles(){return `<div class="ac-page-title"><div><span class="ac-eyebrow">КОМАНДА КЛУБА</span><h1>Модераторы</h1></div>${btn('Назначить',"Admin.setSub('players')")}</div>${box('Кто может управлять игроками',hint('Модератор просматривает паспорта и управляет блокировками. Балансы, предметы, роли и настройки доступны только администратору.')+(A.data.roles?.map(p=>`<button class="ac-player-row" onclick="Admin.open(${p.telegram_id},'roles')"><span class="ac-avatar">${esc(p.avatar||'🎣')}</span><span class="ac-person"><b>${esc(p.nickname||p.telegram_name)}</b><small>ID ${p.telegram_id} · ${esc(p.prefix||'Без префикса')}</small></span>${icon('arrow')}</button>`).join('')||'<div class="ac-empty">Модераторы ещё не назначены.</div>'))}`}
 function system(){const m=A.data.maint||{},D=A.data.stats||{};return `<div class="ac-page-title"><div><span class="ac-eyebrow">ИНФРАСТРУКТУРА</span><h1>Сервер</h1></div></div>${box('Доступ к игре',`<div class="ac-server-status ${m.enabled?'closed':''}">${icon('system')}<div><b>${m.enabled?'Технические работы':'Игра открыта'}</b><small>${m.enabled?'Игроки видят экран обслуживания':'Рыбаки могут заходить в игру'}</small></div><i></i></div><label>Сообщение на экране обслуживания<textarea id="ac-maint-message" maxlength="500" rows="3">${esc(m.message||'')}</textarea></label><div class="ac-button-row">${btn(m.enabled?'Обновить сообщение':'Включить техработы','Admin.maintenance(true)',m.enabled?'':'danger')}${btn('Открыть игру','Admin.maintenance(false)','ghost',!m.enabled)}</div>`)}${box('Диагностика',`<div class="ac-check-list">${(D.checks||[]).map(c=>`<div><span class="ac-check-dot ${c.s}"></span><span><b>${esc(c.n)}</b><small>${esc(c.d)}</small></span><strong>${({ok:'OK',warn:'Внимание',fail:'Ошибка',skip:'—'})[c.s]||c.s}</strong></div>`).join('')}</div>${btn(icon('refresh')+' Проверить базу','Admin.deepCheck()','ghost')}`)}<details class="ac-box ac-system-details"><summary>Техническая информация</summary><div class="ac-facts">${Object.entries(D.info||{}).map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</div></details>`}
 function messages(){const b=A.data.broadcast||{};return `<div class="ac-page-title"><div><span class="ac-eyebrow">СВЯЗЬ С РЫБАКАМИ</span><h1>Сообщения</h1></div></div><div class="ac-two">${box('Личное сообщение',`<form onsubmit="event.preventDefault();Admin.message(false)"><label>Telegram ID игрока<input id="ac-message-id" type="number" min="1" required placeholder="ID из паспорта игрока" value="${A.messageTarget||''}"></label><label>Сообщение<textarea id="ac-message-text" rows="5" maxlength="1000" required placeholder="Текст от имени бота"></textarea></label><button class="ac-btn" data-ac-submit>Отправить игроку</button></form>`)}${box('Рассылка',`<form onsubmit="event.preventDefault();Admin.message(true)"><p class="ac-hint">Сообщение получат все незаблокированные игроки.</p><label>Текст рассылки<textarea id="ac-broadcast-text" rows="5" maxlength="1000" required placeholder="Новости клуба"></textarea></label><button class="ac-btn" data-ac-submit ${b.running?'disabled':''}>${b.running?'Рассылка идёт…':'Подготовить рассылку'}</button></form><div class="ac-broadcast-status" id="ac-broadcast-status">Отправлено ${fmt(b.sent)} / ${fmt(b.total)} · ошибок ${fmt(b.failed)}</div>`)}</div>`}
 function logs(){return `<div class="ac-page-title"><div><span class="ac-eyebrow">ИСТОРИЯ ИЗМЕНЕНИЙ</span><h1>Журнал</h1></div></div><section class="ac-box ac-log">${(A.data.log||[]).map(l=>`<article><i></i><div><div><b>${esc(({coins:'Изменение денег',xp:'Изменение опыта',block:'Блокировка',staff:'Роли и префиксы',case_settings:'Настройка кейса',luck:'Удача',reset:'Сброс аккаунта',clear_bag:'Очистка рюкзака'})[l.action]||l.action)}</b><time>${date(l.ts)}</time></div><p>${l.target?'Игрок '+l.target:'Система'} · ${esc(l.value||'')}</p><small>Администратор ${l.admin_id}</small></div></article>`).join('')||'<div class="ac-empty">Изменений пока нет.</div>'}</section>`}
 function view(){if(!isAdmin()&&A.sub!=='players')A.sub='players';const keys=isAdmin()?Object.keys(names):['players'];const body={overview,players,cases,promos,roles,system,messages,log:logs};return `<div class="ac-shell"><aside class="ac-sidebar"><div class="ac-brand"><span>V</span><div>VIVA<small>CONTROL ROOM</small></div></div><div class="ac-nav-caption">${isAdmin()?'УПРАВЛЕНИЕ':'МОДЕРАЦИЯ'}</div><nav class="ac-nav">${keys.map(k=>`<button class="${A.sub===k?'active':''}" onclick="Admin.setSub('${k}')">${icon(k)}<span>${names[k]}</span>${A.sub===k?'<i></i>':''}</button>`).join('')}</nav><div class="ac-sidebar-note">${icon('roles')}<span>${isAdmin()?'Администратор':'Модератор'}<small>Доступ подтверждён</small></span></div></aside><div class="ac-workspace"><div class="ac-toolbar"><span>${icon(A.sub)} ${names[A.sub]}</span><div><span class="ac-updated">${new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</span><button class="ac-icon-button" onclick="Admin.load()" aria-label="Обновить">${icon('refresh')}</button></div></div>${A.error?`<div class="ac-error">${esc(A.error)} ${btn('Повторить','Admin.load()','ghost')}</div>`:''}<div class="ac-content">${A.loading?loading():body[A.sub]()}</div></div></div>`}
 async function open(uid,cardTab='passport'){await busy(async()=>{let c;if(isAdmin())c=await api('/api/admin/player?id='+uid);else{const s=await api('/api/v11/players/'+uid);c={...s.player,fishing:s,is_admin:s.role==='admin'}}A.card=c;A.cardTab=cardTab;renderCard()})}
 function close(){A.card=null;$('modal').hidden=true}
 function renderCard(){const c=A.card;if(!c)return;const f=c.fishing,id=c.telegram_id,tabs=isAdmin()?[['passport','Паспорт'],['balance','Баланс'],['inventory','Инвентарь'],['roles','Роль'],['security','Безопасность']]:[['passport','Паспорт'],['security','Блокировка']];if(!tabs.some(([k])=>k===A.cardTab))A.cardTab='passport';const stats=[['Уровень',f.level.level],['Доллары','$'+fmt(c.coins)],['Уловы',fmt(f.progress.catches)],['Рекорд',weightText(f.best_kg)+' кг'],['Подсак',f.catches.length+' / 30'],['Снаряжение',f.gear.reduce((n,g)=>n+g.amount,0)+' / 20']];
 const passport=`<div class="ac-passport" style="--passport:${f.profile.color}"><div class="ac-passport-top"><span>VIVA FISHING</span><span>ПАСПОРТ РЫБАКА</span></div><div class="ac-passport-person"><span>${esc(c.avatar==='🏠'?'🎣':c.avatar)}</span><div><h2>${esc(c.nickname||c.telegram_name)}</h2><span class="prefix">${esc(f.profile.prefix||'Рыбак клуба')}</span><p>№ ${id}</p></div></div><div class="ac-passport-foot"><span>Зарегистрирован ${date(c.created_at)}</span><b>${c.blocked?'Доступ закрыт':'Активный профиль'}</b></div></div><div class="ac-passport-stats">${stats.map(([n,v])=>`<div><small>${n}</small><b>${v}</b></div>`).join('')}</div><div class="ac-facts"><div><span>Был онлайн</span><b>${ago(c.last_seen)}</b></div><div><span>Опыт</span><b>${fmt(f.level.xp)} EXP</b></div><div><span>Попытки</span><b>${f.attempts.remaining} / 5</b></div></div>${isAdmin()?`<div class="ac-button-row">${btn('Изменить баланс',"Admin.cardTab('balance')")}${btn('Написать игроку',`Admin.compose(${id})`,'ghost')}</div>`:''}`;
 const balance=`<h2>Деньги и опыт</h2>${hint('Выбери показатель и операцию. Результат будет показан до сохранения.')}<form onsubmit="event.preventDefault();Admin.balance()"><div class="ac-form-grid"><label>Показатель<select id="ac-balance-kind" onchange="Admin.previewBalance()"><option value="coins">Доллары ($${fmt(c.coins)})</option><option value="xp">Опыт (${fmt(f.level.xp)} EXP)</option></select></label><label>Действие<select id="ac-balance-op" onchange="Admin.previewBalance()"><option value="add">Прибавить</option><option value="subtract">Списать</option><option value="set">Установить</option></select></label><label class="wide">Количество<input id="ac-balance-value" type="number" min="0" max="1000000000" step="1" value="1000" required oninput="Admin.previewBalance()"></label></div><div class="ac-balance-preview" id="ac-balance-preview"></div><button class="ac-btn" data-ac-submit>Сохранить изменение</button></form><hr><h2>Временная удача</h2>${hint(f.buff.active?'Сейчас ×'+f.buff.multiplier+' до '+date(f.buff.expires_at):'Активного бонуса нет.')}<div class="ac-form-grid"><label>Множитель<select id="ac-luck-factor"><option value="2">×2</option><option value="3">×3</option><option value="5">×5</option></select></label><label>Длительность, минут<input id="ac-luck-minutes" type="number" min="1" max="43200" value="30"></label></div><div class="ac-button-row">${btn('Выдать удачу','Admin.luck(false)')}${btn('Снять бонус','Admin.luck(true)','ghost',!f.buff.active)}</div>`;
 const inventory=`<h2>Выдача предметов</h2><form onsubmit="event.preventDefault();Admin.grant()"><div class="ac-form-grid"><label>Категория<select id="ac-grant-kind" onchange="Admin.grantOptions()"><option value="gear">Снаряжение</option><option value="fish">Рыба</option><option value="case">Кейсы</option></select></label><label>Действие<select id="ac-grant-op"><option value="add">Выдать</option><option value="remove">Забрать</option></select></label><label class="wide">Предмет<select id="ac-grant-key"></select></label><label class="wide">Количество<input id="ac-grant-count" type="number" min="1" max="1000" step="1" value="1" required></label></div><button class="ac-btn" data-ac-submit>Применить к инвентарю</button></form><h2 class="ac-section-title">Содержимое рюкзака</h2>${[['Снаряжение',f.gear],['Рыба в подсаке',f.catches],['Кейсы',f.cases.filter(c=>c.amount)]].map(([n,rows])=>`<details class="ac-inventory-group"><summary>${n}<b>${rows.reduce((v,x)=>v+(x.amount||1),0)}</b></summary>${rows.map(x=>`<div><span>${esc(x.name)}</span><b>${x.kg?weightText(x.kg)+' кг':'×'+x.amount}</b></div>`).join('')||hint('Пусто')}</details>`).join('')}`;
 const roles=`<h2>Роль и префикс</h2>${hint('Префикс отображается под ником в профиле и рядом с именем в рейтингах.')}<form onsubmit="event.preventDefault();Admin.saveRole()"><label>Префикс<select id="ac-role-prefix"><option value="">Без префикса</option>${S.prefixes.map(x=>`<option ${f.profile.prefix===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="ac-role-toggle"><input id="ac-role-moderator" type="checkbox" ${f.profile.moderator?'checked':''} ${c.is_admin?'disabled':''}><span><b>Модератор</b><small>Просмотр игроков, блокировка и разблокировка. Финансы и настройки недоступны.</small></span></label><button class="ac-btn" data-ac-submit>Сохранить роль и префикс</button></form>`;
 const security=`<h2>Доступ к игре</h2><div class="ac-access-status ${c.blocked?'blocked':''}">${c.blocked?'Игрок заблокирован':'Игрок может заходить в игру'}</div><label>Причина<textarea id="ac-block-reason" rows="3" maxlength="300" placeholder="Причина блокировки">${esc(c.reason||'')}</textarea></label><button class="ac-btn ${c.blocked?'':'danger'}" data-ac-submit onclick="Admin.block(${!c.blocked})" ${c.is_admin?'disabled':''}>${c.blocked?'Разблокировать игрока':'Заблокировать игрока'}</button>${isAdmin()?`<details class="ac-service-actions"><summary>Служебные действия</summary>${hint('Помощь игроку с текущей сессией.')}<div class="ac-button-row">${btn('Восстановить 5 попыток',"Admin.act('cooldown')",'ghost')}${btn('Завершить вываживание',"Admin.act('end_cast')",'ghost')}</div></details><details class="ac-danger-zone"><summary>Сброс данных</summary>${hint('Эти действия удаляют прогресс. Перед выполнением потребуется ввести ID игрока.')}<div class="ac-button-row">${btn('Очистить рюкзак',"Admin.danger('clear_bag')",'danger')}${btn('Сбросить аккаунт',"Admin.danger('reset')",'danger',c.is_admin)}</div></details>`:''}`;
 const parts={passport,balance,inventory,roles,security};$('modal').hidden=false;$('modal').innerHTML=`<section class="ac-player-sheet" role="dialog" aria-modal="true" aria-label="Паспорт игрока"><header class="ac-sheet-header"><div><span class="ac-eyebrow">ИГРОК · ${id}</span><h2>${esc(c.nickname||c.telegram_name)}</h2></div><button class="ac-icon-button" onclick="Admin.close()" aria-label="Закрыть">${icon('close')}</button></header><nav class="ac-card-tabs">${tabs.map(([k,n])=>`<button class="${A.cardTab===k?'active':''}" onclick="Admin.cardTab('${k}')">${n}</button>`).join('')}</nav><div class="ac-sheet-body">${parts[A.cardTab]}</div><footer class="ac-sheet-footer"><span>${icon('roles')} ${isAdmin()?'Изменения сохраняются в журнале':'Доступ модератора'}</span>${btn('Закрыть','Admin.close()','ghost')}</footer></section>`;if(A.cardTab==='balance')previewBalance();if(A.cardTab==='inventory')grantOptions();
 }
 async function refreshCard(){const id=A.card.telegram_id;if(isAdmin())A.card=await api('/api/admin/player?id='+id);else{const s=await api('/api/v11/players/'+id);A.card={...s.player,fishing:s,is_admin:s.role==='admin'}}if(id===S.player.telegram_id){accept(A.card.fishing);render()}renderCard()}
 function cardTab(t){A.cardTab=t;renderCard()}
 function previewBalance(){if(!$('ac-balance-kind'))return;const kind=$('ac-balance-kind').value,op=$('ac-balance-op').value,n=Math.max(0,Number($('ac-balance-value').value)||0),before=kind==='coins'?A.card.coins:A.card.fishing.level.xp,after=op==='set'?n:Math.max(0,before+(op==='subtract'?-n:n));$('ac-balance-preview').innerHTML=`<span>Сейчас<b>${fmt(before)}</b></span><i>→</i><span>После сохранения<b>${fmt(after)}</b></span>`}
 async function balance(){await busy(async()=>{const kind=$('ac-balance-kind').value,op=$('ac-balance-op').value,n=Number($('ac-balance-value').value);if(!Number.isSafeInteger(n)||n<0||n>1e9)throw Error('Нужно целое число от 0 до 1 000 000 000');await api('/api/admin/players/'+A.card.telegram_id,{kind:op==='set'?kind+'_set':kind,delta:op==='subtract'?-n:n});await refreshCard();note('Баланс игрока обновлён','moderator')})}
 function grantOptions(){const f=A.card.fishing,k=$('ac-grant-kind').value,rows={gear:f.catalog.gear,fish:f.catalog.fish,case:f.cases}[k];$('ac-grant-key').innerHTML=rows.map(x=>`<option value="${x.key}">${esc(x.name)}</option>`).join('')}
 async function grant(){await busy(async()=>{const n=Number($('ac-grant-count').value);if(!Number.isSafeInteger(n)||n<1||n>1000)throw Error('Количество: целое число от 1 до 1000');await api('/api/admin/players/'+A.card.telegram_id,{kind:$('ac-grant-kind').value,key:$('ac-grant-key').value,delta:$('ac-grant-op').value==='remove'?-n:n});await refreshCard();note('Инвентарь обновлён','moderator')})}
 async function luck(remove){await busy(async()=>{await api('/api/admin/players/'+A.card.telegram_id+'/luck',{multiplier:remove?1:Number($('ac-luck-factor').value),minutes:remove?1:Number($('ac-luck-minutes').value)});await refreshCard();note('Бонус удачи обновлён','moderator')})}
 async function saveRole(){await busy(async()=>{await api('/api/v11/admin/staff',{uid:A.card.telegram_id,prefix:$('ac-role-prefix').value,moderator:$('ac-role-moderator').checked});await refreshCard();note('Роль и префикс сохранены','moderator')})}
 async function block(blocked){await busy(async()=>{await api('/api/v11/players/'+A.card.telegram_id+'/block',{blocked,reason:$('ac-block-reason').value});await refreshCard();note(blocked?'Игрок заблокирован':'Доступ восстановлен','moderator')})}
 async function act(action){await busy(async()=>{await api('/api/admin/act',{telegram_id:A.card.telegram_id,act:action});await refreshCard();note('Готово','moderator')})}
 function confirmAction(title,text,fn,typed=''){const previous=$('modal').innerHTML,wasHidden=$('modal').hidden;A.confirm={fn,previous,wasHidden,typed};$('modal').hidden=false;$('modal').innerHTML=`<section class="ac-confirm"><span class="ac-eyebrow">ПОДТВЕРЖДЕНИЕ</span><h2>${esc(title)}</h2><p>${esc(text)}</p>${typed?`<label>Введи ID ${esc(typed)}<input id="ac-confirm-id" inputmode="numeric" autocomplete="off"></label>`:''}<div class="ac-button-row">${btn('Отмена','Admin.cancelConfirm()','ghost')}<button class="ac-btn ${typed?'danger':''}" onclick="Admin.confirmDo()">Подтвердить</button></div></section>`}
 function cancelConfirm(){if(!A.confirm)return;const c=A.confirm;A.confirm=null;$('modal').innerHTML=c.previous;$('modal').hidden=c.wasHidden;if(A.card&&!c.wasHidden)renderCard()}
 async function confirmDo(){const q=A.confirm;if(!q)return;if(q.typed&&$('ac-confirm-id').value.trim()!==q.typed)return note('ID не совпадает','error');A.confirm=null;$('modal').hidden=q.wasHidden;$('modal').innerHTML=q.previous;await q.fn()}
 function danger(kind){const id=A.card.telegram_id;confirmAction(kind==='reset'?'Сбросить аккаунт?':'Очистить рюкзак?',kind==='reset'?'Будут удалены деньги, опыт и инвентарь этого игрока.':'Будет удалена рыба из подсака и аквариума.',()=>act(kind),String(id))}
 function editCase(key){A.caseKey=key;render()}
 function chances(){const inputs=[...document.querySelectorAll('[data-ac-weight]')],sum=inputs.reduce((n,e)=>n+Math.max(0,Number(e.value)||0),0);inputs.forEach(e=>{document.querySelector(`[data-ac-chance="${e.dataset.acWeight}"]`).textContent=chanceText(sum?Math.max(0,Number(e.value)||0)/sum*100:0)});$('ac-case-total').textContent=sum?'Итоговая вероятность: 100%':'Добавь хотя бы один предмет'}
 async function saveCase(){await busy(async()=>{const weights={};document.querySelectorAll('[data-ac-weight]').forEach(e=>weights[e.dataset.acWeight]=Number(e.value));await api('/api/admin/cases/'+A.caseKey,{price:Number($('ac-case-price').value),enabled:$('ac-case-enabled').value==='true',weights});note('Кейс обновлён','moderator');await load()})}
 async function createPromo(){await busy(async()=>{await api('/api/v11/admin/promo',{code:$('ac-promo-code').value,coins:Number($('ac-promo-coins').value),xp:Number($('ac-promo-xp').value),uses:Number($('ac-promo-uses').value),hours:Number($('ac-promo-hours').value)});note('Промокод создан','moderator');await load()})}
 function maintenance(enabled){const message=$('ac-maint-message').value;const change=()=>busy(async()=>{await api('/api/admin/maintenance',{enabled,message});note(enabled?'Технические работы включены':'Игра открыта','moderator');await load()});if(enabled&&!A.data.maint?.enabled)confirmAction('Включить технические работы?','Обычные игроки увидят экран обслуживания. Ты сохранишь доступ к управлению.',change);else change()}
 async function deepCheck(){await busy(async()=>{A.data.stats=await api('/api/admin/stats?deep=true');render();note('Проверка завершена','success')})}
 function compose(id){close();A.messageTarget=id;setSub('messages')}
 function message(broadcast){const id=Number($('ac-message-id')?.value),text=$(broadcast?'ac-broadcast-text':'ac-message-text').value.trim();if(!text)return note('Введите текст','error');if(!broadcast&&(!Number.isSafeInteger(id)||id<=0))return note('Нужен ID игрока','error');confirmAction(broadcast?'Отправить рассылку?':'Отправить сообщение?',(broadcast?'Все незаблокированные игроки':`Игрок ${id}`)+' получат сообщение:\n\n'+text,()=>busy(async()=>{await api('/api/admin/'+(broadcast?'broadcast':'message'),broadcast?{text}:{telegram_id:id,text});note('Сообщение передано боту','success');await load()}))}
 setInterval(async()=>{if(tab!=='admin'||A.sub!=='messages'||!A.data.broadcast?.running||document.hidden)return;try{A.data.broadcast=await api('/api/admin/broadcast');const b=A.data.broadcast;if($('ac-broadcast-status'))$('ac-broadcast-status').textContent=`Отправлено ${b.sent} / ${b.total} · ошибок ${b.failed}`}catch(_){}},3000);
 return {view,load,setSub,open,close,cardTab,balance,previewBalance,grantOptions,grant,luck,saveRole,block,act,danger,confirmDo,cancelConfirm,editCase,chances,saveCase,createPromo,maintenance,deepCheck,compose,message,search(){A.q=$('ac-search').value.trim();A.page=0;load()},filter(k){A.filter=k;A.page=0;load()},sort(k){A.sort=k;A.page=0;load()},page(d){A.page=Math.max(0,A.page+d);load()},setInitial(k){A.sub=k}};
})();
const goBeforeAdminV12=go;go=function(t){if(t==='staff'){Admin.setInitial('players');t='admin'}goBeforeAdminV12(t)};
staffCard=uid=>Admin.open(uid,'roles');

