el.insertAdjacentHTML('afterbegin',cards.map(([key,emoji,title,sub,tone])=>`<button class="menu-v13-card tone-${tone}" onclick="go('${key}')"><span class="menu-v13-emoji">${emoji}</span><span class="menu-v13-card-arrow">↗</span><b>${title}</b><small>${sub}</small></button>`).join(''));
