// Функция vivaAdminScreen: логика соответствующего элемента интерфейса.
function vivaAdminScreen(d){const settings=d.settings,partners=d.partners,sections=d.sections;
$('view').innerHTML=`<div class="brand">VIVA · BETA V1</div><h1>Управление V14</h1>${vivaCard('Настройки наград и набора',Object.entries(settings).map(([k,val])=>`<label>${esc(k)}<input data-viva-setting="${esc(k)}" value="${esc(val)}" maxlength="50"></label>`).join('')+`<button class="full" onclick="vivaSaveSettings()">Сохранить настройки</button>`)}${vivaCard('Разделы на техработах', ['fish','bag','shop','donate','pass','referral','chat','rewards','top','profile','partner'].map(s=>`<label class="v14-switch"><input type="checkbox" ${sections.some(x=>x.section===s&&x.enabled)?'checked':''} onchange="vivaSetSection('${s}',this.checked)"> ${s}</label>`).join(''))}${vivaCard('Заявки партнёров',partners.map(p=>`<div class="v14-partner"><b>${p.uid}</b><p>${esc(p.description)} · ${esc(p.status)}</p><button onclick="vivaApprove(${p.uid},true)">Одобрить</button> <button onclick="vivaApprove(${p.uid},false)">Отклонить</button></div>`).join('')||'<p>Нет заявок</p>')}${vivaCard('База данных',`<p>Скачать актуальный безопасный снимок SQLite.</p><button class="full" onclick="vivaBackup()">💾 Скачать базу</button><p>Восстановление файла доступно через чат с ботом. Загруженная база сначала проверяется и подготавливается; для применения необходимо остановить сервер.</p>`)}<button class="ghost full" onclick="go('admin')">← Основная админ-панель</button>`}
// Функция vivaSaveSettings: логика соответствующего элемента интерфейса.
async function vivaSaveSettings(){await run(async()=>{for(const el of document.querySelectorAll('[data-viva-setting]'))await api('/api/v14/admin/settings',{key:el.dataset.vivaSetting,value:el.value.trim()});note('Настройки сохранены','success');await vivaAdminLoad()})}
// Функция vivaSetSection: логика соответствующего элемента интерфейса.
async function vivaSetSection(section,enabled){await run(async()=>{await api('/api/v14/admin/section',{section,enabled});note('Статус раздела изменён','success')})}
// Функция vivaApprove: логика соответствующего элемента интерфейса.
async function vivaApprove(uid,approved){await run(async()=>{await api('/api/v14/admin/partner',{uid,approved});await vivaAdminLoad()})}
// Функция vivaBackup: логика соответствующего элемента интерфейса.
async function vivaBackup(){await run(async()=>{const response=await fetch('/api/v14/admin/backup',{method:'POST',headers:{'X-Telegram-Init-Data':tg?.initData||''}});const result=await response.json();if(!response.ok)throw Error(result.detail||'Ошибка отправки базы');if(typeof toast==='function')toast(result.message);else alert(result.message);})}
const oldPaintAdmin14=paint;paint=function(){oldPaintAdmin14();if(tab==='admin'&&S?.role==='admin')$('view')?.insertAdjacentHTML('afterbegin','<button class="full" onclick="go(\'viva_admin\')">⭐ Управление Viva Beta V1</button>');if(tab==='viva_admin'&&!document.querySelector('.v14-admin-loaded')){document.querySelector('#view').innerHTML='<div class="v14-admin-loaded">Загрузка настроек…</div>';vivaAdminLoad()}};

// ===== layer: v15.js =====
'use strict';
/* Beta V1 presentation enhancements; no fabricated client-side rewards. */
const vivaRank={common:0,uncommon:1,rare:2,epic:3,professional:4,legendary:5,mythic:6,secret:7,exclusive:8,unique:9};
const vivaSort=(a,b)=>(vivaRank[b.rarity]??0)-(vivaRank[a.rarity]??0)||(Number(b.kg||b.max_kg||0)-Number(a.kg||a.max_kg||0));
const vivaPct=n=>Number(n||0).toLocaleString('ru-RU',{maximumFractionDigits:1})+'%';
const vivaMoney=n=>Math.floor(Number(n||0)).toLocaleString('ru-RU');
const vivaCompact=n=>{n=Number(n)||0;const abs=Math.abs(n);let d=abs>=1e9?[1e9,'млрд']:abs>=1e6?[1e6,'м']:abs>=1e3?[1e3,'к']:null;return d?(n/d[0]).toLocaleString('ru-RU',{maximumFractionDigits:1})+d[1]:vivaMoney(n)};
let vivaExpandedBalance=false;
// Функция vivaBalanceToggle: логика соответствующего элемента интерфейса.
function vivaBalanceToggle(){vivaExpandedBalance=!vivaExpandedBalance;vivaHeader();}
// Функция vivaHeader: логика соответствующего элемента интерфейса.
function vivaHeader(){const h=$('header');if(!S||!h)return;const w=h.querySelector('.wallet');if(w){w.setAttribute('role','button');w.setAttribute('tabindex','0');w.setAttribute('title','Нажми для просмотра точного баланса');w.onclick=vivaBalanceToggle;w.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();vivaBalanceToggle()}};w.textContent='$ '+(vivaExpandedBalance?vivaMoney(S.player.coins):vivaCompact(S.player.coins));}const a=h.querySelector('.avatar');if(a){const l=S.level.level;a.style.setProperty('--viva-level-color',l<5?'#f0f5fa':l<10?'#4fafff':l<15?'#ab82ff':l<20?'#ffb84d':'#ef79db')}}
const vivaOldPaint=paint;paint=function(){vivaOldPaint();vivaHeader();};
const vivaOldBag=bagView;bagView=function(){if(!S)return;S.catches?.sort(vivaSort);S.gear?.sort(vivaSort);S.aquarium?.fish?.sort(vivaSort);vivaOldBag();let tabs=document.querySelectorAll('.bag-tabs:first-of-type button');const icons=['🐟','🎣','🫧'];tabs.forEach((b,i)=>{if(i<3&&!b.textContent.includes(icons[i]))b.prepend(document.createTextNode(icons[i]+' '))});if(bagTab==='tank'){const panel=$('view').querySelector('.tank-panel');if(panel&&!panel.querySelector('.viva-water')){panel.insertAdjacentHTML('afterbegin',`<div class="viva-water" aria-hidden="true">${S.aquarium.fish.map((f,i)=>`<span class="viva-fish-shadow" style="--f:${i};--speed:${9+i*3}s">◆</span>`).join('')}<span class="viva-water-glow"></span></div>`);panel.querySelector('button')?.classList.add('viva-claim');}updateTank();}};
const vivaOldUpdateTank=updateTank;updateTank=function(){vivaOldUpdateTank();const b=$('tank-balance');if(b){const t=S.aquarium,now=(Date.now()+offset)/1000,delta=Math.max(0,Math.min(now,t.cap_at)-Math.min(t.server_time,t.cap_at));b.textContent='$'+vivaMoney(t.balance+delta*t.rate/3600);}};
// Функция vivaFishDetails: логика соответствующего элемента интерфейса.
function vivaFishDetails(id){const f=S.catches.find(x=>x.id===id);if(!f)return;$('modal').hidden=false;$('modal').innerHTML=`<section class="equipment-sheet viva-fish-detail rarity-${esc(f.rarity)}"><button class="ghost sm viva-x" onclick="closeModal()">✕</button>${itemArt(f,'collect-art')}${rarity(f)}<h2>${esc(f.name)}</h2><p>${weightText(f.kg)} кг · $${vivaMoney(f.value)}</p><div class="viva-detail-buttons"><button onclick="closeModal();action('sell',{fish_key:'${f.id}'})">💰 Продать</button><button class="ghost" onclick="closeModal();vaction('tank',{action:'add',id:${f.id}})">🫧 В аквариум</button><button class="ghost" onclick="vivaRelease(${f.id})">🌊 Отпустить · XP</button><button class="ghost" disabled title="Рынок появится позже">🔒 Рынок</button></div><button class="ghost full" onclick="closeModal()">Закрыть</button></section>`;}
const vivaOldFishCard=fishCard;fishCard=function(f,place='bag'){if(place==='tank')return vivaOldFishCard(f,place);return `<button class="viva-fish-click" onclick="vivaFishDetails(${Number(f.id)})" aria-label="Открыть карточку ${esc(f.name)}">${rarity(f)}${itemArt(f,'collect-art')}<strong>${esc(f.name)}</strong><small>${weightText(f.kg)} кг · $${vivaCompact(f.value)}</small></button>`;};
const vivaOldShop=shopView;shopView=function(){if(selectedCase)return vivaOldShop();const groups=[['rod','🎣','Удочки'],['reel','⚙️','Катушки'],['bait','🪝','Приманки']];$('view').innerHTML=`<div class="brand">VIVA · АРСЕНАЛ</div><h1>Кейсы</h1><p class="hint">Выбери категорию и кейс. Шансы и содержимое — внутри выбранного кейса.</p>${groups.map(([key,icon,title])=>{const list=S.cases.filter(c=>c.type===key);return `<section class="viva-case-group"><h2>${icon} ${title}</h2><div class="viva-case-mini-grid">${list.map((c,i)=>`<button class="viva-case-mini" onclick="selectedCase='${esc(c.key)}';caseView()" ${!c.enabled?'disabled':''}><span class="viva-case-symbol">${icon}</span><strong>${esc(c.name)}</strong><small>${['Базовый','Средний','Премиум'][Math.min(i,2)]} · $${vivaCompact(c.price)}</small>${c.amount?`<em>Есть: ${c.amount}</em>`:''}</button>`).join('')||'<p>Нет доступных кейсов</p>'}</div></section>`}).join('')}`;};
const vivaOldCaseView=caseView;caseView=function(){vivaOldCaseView();const root=$('view');let collection=root.querySelector('.collection-grid');if(collection){const c=S.cases.find(c=>c.key===selectedCase);const title=collection.previousElementSibling;const hint=title?.previousElementSibling;if(hint?.classList.contains('hint'))hint.textContent='Перед открытием освободи место в рюкзаке. Максимум 6 предметов каждого типа.';const wrap=document.createElement('details');wrap.className='panel viva-case-chances';wrap.innerHTML='<summary>📋 Возможные награды и шансы</summary>';collection.before(wrap);wrap.append(collection);collection.innerHTML=(c?.rewards||[]).slice().sort(vivaSort).map(g=>`<div class="odds-row">${itemArt(g,'odds-art')}<span><b>${esc(g.name)}</b><small>${rarity(g)}</small></span><strong>${vivaPct(g.chance)}</strong></div>`).join('');if(title?.tagName==='H2')title.remove();}const btn=$('case-open');if(btn){const c=S.cases.find(c=>c.key===selectedCase),count=S.gear.filter(g=>g.type===c?.type).reduce((n,g)=>n+(g.amount||1),0);const free=6-count;let hint=document.createElement('p');hint.className='hint';hint.textContent=`Мест занято: ${count}/6 · свободно: ${free}`;btn.after(hint);if(caseCount>free){btn.disabled=true;btn.textContent=`🔒 Освободи ${caseCount-free} мест`}}};
const vivaOldOpenCase=open11Case;open11Case=async function(){await vivaOldOpenCase();const results=$('case-results');if(results&&results.children.length){results.classList.add('viva-reveal');results.insertAdjacentHTML('beforeend','<div class="viva-case-actions"><button class="ghost full" onclick="caseView()">↻ Крутить ещё</button><button class="ghost full" onclick="go(\'bag\');bagTab=\'gear\';bagView()">🎒 Моя экипировка</button></div>');}};
const vivaOldTop=topView;topView=function(){vivaOldTop();const list=$('top-list');if(list){const id=S.player.telegram_id;const pos=topRows.findIndex(p=>p.telegram_id===id);list.insertAdjacentHTML('afterend',`<div class="viva-my-rank">👤 ${pos<0?'Твоё место вне первой десятки':`Ты в топе: #${pos+1}`}</div>`);}};
const vivaOldFishView=fishView;fishView=function(){vivaOldFishView();const odds=$('view').querySelector('details.panel');if(odds){const rows=[...odds.querySelectorAll('.odds-row')];rows.sort((a,b)=>{const ranks=Object.keys(vivaRank);const rank=x=>Math.max(...ranks.map((s,i)=>x.querySelector('.rarity')?.classList.contains(s)?i:-1));return rank(a)-rank(b)}).forEach(r=>odds.append(r));}const scene=$('view').querySelector('.scene-wrap');if(scene)scene.insertAdjacentHTML('afterend',`<div class="viva-location-buttons">${S.locations.map((l,i)=>`<button class="${i===loc?'on':''}" onclick="loc=${i};fishView()">${S.level.level<l.level?'🔒 ':''}${esc(l.name)}</button>`).join('')}</div>`);};

// Функция vivaRelease: логика соответствующего элемента интерфейса.
async function vivaRelease(id){await run(async()=>{const r=await api('/api/v11/fish/release',{id});accept(r.state);closeModal();paint();note('Рыба отпущена · +'+r.xp+' XP','success');});}

