/* Viva Beta V1 polished Shop & Pass */
'use strict';
// Функция v16Reward: логика соответствующего элемента интерфейса.
function v16Reward(level,vip){const coins=level*(vip?900:300),cases=level%5===0?(vip?'Средний кейс удочек':'Базовый кейс удочек'):null,clover=vip&&level%10===0?2:0;return {coins,cases,clover};}
// Функция v16RewardHTML: логика соответствующего элемента интерфейса.
function v16RewardHTML(level,vip){const r=(viva14?.pass_rewards?.[level-1]?.[vip?'premium':'free'])||v16Reward(level,vip);return `<span class="v16-reward-money">💰 ${fmt(r.coins)} $</span>${r.cases?`<span class="v16-reward-extra">📦 ${(Array.isArray(r.cases)?r.cases.map(k=>({rod_0:"Базовый кейс удочек",rod_1:"Средний кейс удочек"}[k]||k)).join(", "):r.cases)}</span>`:''}${r.clover?`<span class="v16-reward-extra">🍀 Клевер ×2 · ${r.clover} ч</span>`:''}`}
// Функция v16Progress: логика соответствующего элемента интерфейса.
function v16Progress(v){let lvl=Math.max(0,Math.min(30,Number(v.pass_level)||0));return `<section class="v16-hero"><span class="v16-eyebrow">СЕЗОННЫЕ НАГРАДЫ · 30 УРОВНЕЙ</span><div class="v16-heading"><h1>Viva <em>Pass</em></h1><span class="v16-rank">${lvl}/30</span></div><div class="v16-meter" role="progressbar" aria-valuenow="${lvl}" aria-valuemin="0" aria-valuemax="30"><span style="width:${lvl/30*100}%"></span></div><p>Разблокируй награды, повышая уровень на рыбалке. Бесплатная ветка доступна каждому.</p><div class="v16-summary"><span>✓ Бесплатно собрано: <b>${v.pass_claim}/30</b></span><span>★ ViVip собрано: <b>${v.vip_claim}/30</b></span></div></section>`}
// Функция v16ClaimButton: логика соответствующего элемента интерфейса.
function v16ClaimButton(v,level,vip){const taken=level<=(vip?v.vip_claim:v.pass_claim),unlocked=level<=v.pass_level,owned=!vip||v.vivip,next=level===(vip?v.vip_claim:v.pass_claim)+1,enabled=owned&&unlocked&&next&&!taken;const text=taken?'✓ Получено':!owned?'🔒 ViVip':!unlocked?'🔒 Уровень '+level:!next?'Сначала предыдущую':'Забрать';return `<button class="v16-claim ${enabled?'ready':''}" ${enabled?'':'disabled'} onclick="vivaAction('pass/claim',{track:'${vip?'vivip':'viva'}',level:${level}})">${text}</button>`}
// Функция v16Pass: логика соответствующего элемента интерфейса.
function v16Pass(v){const rows=Array.from({length:30},(_,i)=>{let n=i+1;return `<div class="v16-pass-row ${n<=v.pass_level?'available':''}" id="v16-level-${n}"><article class="v16-prize premium"><small>★ ПРЕМИУМ</small><div class="v16-rewards">${v16RewardHTML(n,true)}</div>${v16ClaimButton(v,n,true)}</article><div class="v16-level"><span>${n}</span><i></i></div><article class="v16-prize basic"><small>✦ БЕСПЛАТНО</small><div class="v16-rewards">${v16RewardHTML(n,false)}</div>${v16ClaimButton(v,n,false)}</article></div>`}).join('');return `<div class="v16-page v16-pass-page"><button class="v16-back" onclick="go('menu')">← Меню</button>${v16Progress(v)}<section class="v16-upgrade"><div><small>VIP-ДОРОЖКА</small><h2>${v.vivip?'👑 ViVip активен':'👑 Открой ViVip'}</h2><p>${v.vivip?'Все премиальные награды можно получать при достижении уровня.':'Дополнительные награды за каждый из 30 уровней. Уже достигнутые уровни тоже доступны.'}</p></div>${v.vivip?'<span class="v16-owned">✓ Приобретён</span>':`<button class="v16-gold-btn" onclick="vivaAction('buy',{product:'vivip'})">Открыть · ⭐ 250</button>`}</section><div class="v16-lane-head"><span>👑 ViVip <small>Платная</small></span><span>УРОВЕНЬ</span><span>🎁 Viva <small>Бесплатная</small></span></div><div class="v16-pass-track">${rows}</div><p class="v16-footnote">Награды выдаются последовательно. Клевер увеличивает шанс на 2 часа. Один кейс на каждом пятом уровне.</p></div>`}
// Функция v16Shop: логика соответствующего элемента интерфейса.
function v16Shop(v){let nums=[50,100,250,500];const cards=nums.map(n=>`<button class="v16-pack ${n===250?'featured':''}" onclick="vivaInvoice(${n})"><span class="v16-stars-icon">✦</span><strong>${n}</strong><small>ЗВЁЗД VIVA</small><span class="v16-pack-cta">Пополнить →</span></button>`).join('');const starter=v.starter||{};return `<div class="v16-page v16-shop-page"><button class="v16-back" onclick="go('menu')">← Меню</button><section class="v16-shop-hero"><span class="v16-eyebrow">VIVA · МАГАЗИН</span><h1>Viva <em>Shop</em></h1><div class="v16-wallet"><span>Доступный баланс</span><strong>⭐ ${fmt(v.stars)}</strong><small>Внутриигровые звёзды Viva</small></div></section><section class="v16-shop-section"><div class="v16-section-title"><h2>Пополнение</h2><span>Оплата через Telegram</span></div><div class="v16-pack-grid">${cards}</div><p class="v16-hint">Оплата производится Telegram Stars. Звёзды Viva зачисляются после подтверждения оплаты.</p></section><section class="v16-shop-section"><div class="v16-section-title"><h2>Товары</h2><span>За звёзды Viva</span></div><article class="v16-product"><div class="v16-product-emblem">🎒</div><div class="v16-product-info"><span class="v16-product-badge">СТАРТОВЫЙ НАБОР</span><h3>Набор новичка</h3><p>💰 ${fmt(starter.coins||0)} $ · ⚡ ${fmt(starter.xp||0)} XP · 🎣 Экипировка</p><small>Состав и стоимость регулируются администрацией.</small></div><button ${starter.enabled?'':'disabled'} onclick="vivaAction('buy',{product:'starter'})">${starter.enabled?'⭐ '+fmt(starter.price):'Недоступно'}</button></article><article class="v16-product v16-vip-product"><div class="v16-product-emblem">👑</div><div class="v16-product-info"><span class="v16-product-badge">ПРЕМИУМ</span><h3>ViVip</h3><p>30 дополнительных наград: монеты, кейсы и клевер.</p><small>Открывает левую ветку Viva Pass.</small></div><button ${v.vivip?'disabled':''} onclick="${v.vivip?'go(\'pass\')':"vivaAction('buy',{product:'vivip'})"}">${v.vivip?'✓ Куплен':'⭐ 250'}</button></article><button class="v16-link-pass" onclick="go('pass')">Посмотреть все 30 наград Viva Pass →</button></section><p class="v16-footnote">Покупки списываются с баланса Viva. После оплаты баланс обновляется автоматически.</p></div>`}
const v16ScreenOld=vivaScreen;
vivaScreen=function(){if(viva14&&tab==='pass'){$('view').innerHTML=v16Pass(viva14);return;}if(viva14&&tab==='donate'){$('view').innerHTML=v16Shop(viva14);return;}return v16ScreenOld();};

/* Server-controlled chat bans, admin management, and compact bubbles */
let v16ChatBlocked=false;
const v16DrawChat=drawChat;
drawChat=function(){v16DrawChat();const form=document.querySelector('.chat-composer');if(form){const ta=form.querySelector('textarea'),btn=form.querySelector('button');if(ta)ta.disabled=v16ChatBlocked;if(btn)btn.disabled=v16ChatBlocked;if(v16ChatBlocked&&!form.querySelector('.v16-chat-blocked'))form.insertAdjacentHTML('afterbegin','<p class="v16-chat-blocked">🔒 Администратор ограничил возможность отправлять сообщения.</p>');}if(S?.role==='admin')document.querySelectorAll('#chat-messages .chat-message').forEach((row,i)=>{let m=chatMessages[i];if(!m||row.querySelector('.v16-ban-btn'))return;const controls=row.querySelector('.chat-bubble .row');if(controls)controls.insertAdjacentHTML('beforeend',`<button class="v16-ban-btn" onclick="v16Ban(${Number(m.telegram_id)},true)" title="Закрыть доступ к чату">🔒</button>`)});};
const v16LoadChat=loadChat;
loadChat=async function(){await v16LoadChat();if(tab!=='chat')return;try{const result=await api('/api/community/chat');v16ChatBlocked=!!result.blocked;drawChat();}catch(e){console.warn('Chat status:',e)}};
// Функция v16Ban: логика соответствующего элемента интерфейса.
async function v16Ban(uid,banned){if(!confirm(banned?'Заблокировать этому игроку общий чат?':'Разблокировать игрока?'))return;await run(async()=>{await api('/api/community/chat/ban',{uid,banned});note(banned?'Чат заблокирован':'Чат разблокирован','success');await v16LoadBans()})}
// Функция v16LoadBans: логика соответствующего элемента интерфейса.
async function v16LoadBans(){if(S?.role!=='admin')return;try{const response=await api('/api/community/chat/bans');const container=document.querySelector('#v16-banned-players');if(container)container.innerHTML=response.players.length?response.players.map(r=>`<div class="v16-ban-entry"><span>ID ${r.uid}</span><button onclick="v16Ban(${Number(r.uid)},false)">Разблокировать</button></div>`).join(''):'<small>Заблокированных игроков нет</small>';}catch(e){note(e.message,'error')}}
const v16AdminScreenOld=vivaAdminScreen;
vivaAdminScreen=function(data){v16AdminScreenOld(data);$('view').insertAdjacentHTML('beforeend',`<section class="v14-card"><h2>💬 Модерация общего чата</h2><p>Для блокировки открой общий чат и нажми 🔒 рядом с сообщением игрока.</p><h3>Заблокированные игроки</h3><div id="v16-banned-players">Загрузка…</div></section>`);v16LoadBans();};

// ===== layer: v17.js =====
"use strict";
/* Viva V1 finale: cohesive rewards, bulk case controls and location presentation. */
// Функция v17Safe: логика соответствующего элемента интерфейса.
function v17Safe(s){return esc(String(s??''))}
// Функция v17RewardCountdown: логика соответствующего элемента интерфейса.
function v17RewardCountdown(at,seconds){const left=Math.max(0,Number(at||0)+seconds-Math.floor(Date.now()/1000+offset/1000));if(!left)return 'Можно получить';const h=Math.floor(left/3600),m=Math.floor((left%3600)/60),s=left%60;return `${h?`${h} ч `:''}${m} мин ${String(s).padStart(2,'0')} сек`}
const v17OldRewards=rewardsView;
rewardsView=function(){v17OldRewards();const r=S?.rewards||{};const st=Math.min(7,Math.max(0,Number(r.streak)||0));const hourly=!!r.hourly_ready,daily=!!r.daily_ready;const view=$('view');view.innerHTML=`<div class="v17-page"><div class="v17-eyebrow">VIVA · НАГРАДЫ</div><h1>Подарки за активность</h1><p class="v17-lead">Получай монеты, опыт и кейсы. Все награды начисляются сервером.</p><div class="v17-reward-grid"><article class="v17-reward-card v17-hour"><span class="v17-reward-icon">⏱️</span><small>КАЖДЫЙ ЧАС</small><h2>Часовой бонус</h2><div class="v17-reward-pill">💰 100 $</div><div class="v17-reward-pill">⚡ 10 EXP</div><p class="v17-cooldown" data-v17-hour> ${v17RewardCountdown(r.hourly_at,3600)}</p><button class="full" ${hourly?'':'disabled'} onclick="claimReward('hourly')">${hourly?'Забрать награду':'Восстанавливается'}</button></article><article class="v17-reward-card v17-day"><span class="v17-reward-icon">🎁</span><small>КАЖДЫЙ ДЕНЬ</small><h2>Награда дня</h2><div class="v17-reward-pill">💰 500–1 100 $</div><div class="v17-reward-pill">⚡ 50 EXP</div><div class="v17-reward-pill">📦 Береговой кейс</div><p class="v17-cooldown" data-v17-day>${v17RewardCountdown(r.daily_at,86400)}</p><button class="full" ${daily?'':'disabled'} onclick="claimReward('daily')">${daily?'Забрать награду':'Восстанавливается'}</button></article></div><section class="v17-week"><h2>Серия из 7 дней</h2><p>Каждый новый день — на 100 $ больше. После перерыва дольше 48 часов серия начинается заново.</p><div class="v17-days">${Array.from({length:7},(_,i)=>`<span class="${i<st?'collected':''}" title="День ${i+1}: ${500+i*100} $"><b>${i+1}</b><small>${500+i*100}$</small></span>`).join('')}</div></section></div>`;};
let v17RecentRewards=[];
const v17PrevOpenCase=open11Case;
open11Case=async function(){const previous=S?.gear?.map(g=>({key:g.key,amount:g.amount||1}))||[];const old=lock;await v17PrevOpenCase();if(old||!S)return;const changed=S.gear||[];const prev=Object.fromEntries(previous.map(g=>[g.key,g.amount]));const additions=[];for(const g of changed){const diff=(g.amount||1)-(prev[g.key]||0);for(let i=0;i<diff;i++)additions.push(g.key)}if(!additions.length)return;v17RecentRewards=additions;const el=$('case-results');if(el){el.querySelector('.viva-case-actions')?.remove();el.insertAdjacentHTML('beforeend',`<div class="v17-case-actions"><div><b>${additions.length} предмет(ов) получено</b><small>Можно сохранить их или продать. Уже надетую последнюю снасть сервер не продаст.</small></div><div class="v17-action-row"><button onclick="v17KeepCases()">🎒 Оставить всё</button><button class="v17-sell" onclick="v17SellCases()">💰 Продать полученное</button><button class="ghost" onclick="caseView()">↻ Открыть ещё</button></div></div>`);}};
// Функция v17KeepCases: логика соответствующего элемента интерфейса.
function v17KeepCases(){v17RecentRewards=[];document.querySelector('.v17-case-actions')?.remove();note('Снасти оставлены в рюкзаке','success')}
// Функция v17SellCases: логика соответствующего элемента интерфейса.
async function v17SellCases(){if(!v17RecentRewards.length)return;if(!confirm('Продать только что полученные предметы? Надетые предметы сервер защищает от продажи.'))return;await run(async()=>{let sold=0,fail=0;for(const key of v17RecentRewards){try{const r=await api('/api/v11/gear/sell',{key});accept(r.state);sold++}catch(e){fail++}}v17RecentRewards=[];paint();if(selectedCase)caseView();note(`Продано: ${sold}${fail?`; не удалось: ${fail}`:''}`,fail?'info':'success')})}
const v17OldFishView=fishView;
fishView=function(){v17OldFishView();const l=S?.locations?.[loc];if(!l)return;const wrap=$('view').querySelector('.viva-location-buttons');if(wrap){wrap.insertAdjacentHTML('beforebegin',`<div class="v17-location-details"><div><small>ЛОКАЦИЯ</small><strong>${v17Safe(l.name)}</strong></div><div><small>НУЖЕН УРОВЕНЬ</small><strong>${Number(l.level)||1}</strong></div><div><small>ВИДОВ РЫБ</small><strong>${(S.fish_odds?.[l.key]||[]).length}</strong></div></div>`)}const odds=$('view').querySelector('.fish-chances');if(odds){odds.querySelectorAll('.odds-row').forEach(row=>{const chance=row.querySelector('b');if(chance){const n=parseFloat(chance.textContent.replace(',','.'));if(Number.isFinite(n))chance.textContent=vivaPct(n)}})}};
const v17PrevBag=bagView;
bagView=function(){v17PrevBag();if(bagTab==='gear'){const rows=$('view').querySelectorAll('.collect-card');rows.forEach(row=>row.classList.add('v17-gear-card'))}};
const v17PrevMenu=menuView;
menuView=function(){v17PrevMenu();const pass=document.querySelector('.menu-v13-grid [onclick="go(\'pass\')"]');if(pass)pass.classList.add('v17-featured-pass')};

