// ===== layer: v19.js =====
 'use strict';
/* V19: case controls + illustrative, rarity-aware equipment icons. */
const viva19PriorArt=itemArt;
const viva19Colors={common:'#93b4c6',improved:'#70cf9a',rare:'#55b7fa',epic:'#b78aff',marine:'#3ad3d5',legendary:'#ffcd66',secret:'#ff7aa3',exclusive:'#fbbf57'};
// Функция viva19GearSvg: логика соответствующего элемента интерфейса.
function viva19GearSvg(g,extra){const color=viva19Colors[g.rarity]||'#70c9ff';let seed=Array.from(g.key||g.name||'').reduce((a,c)=>a+c.charCodeAt(0),0);const reel=g.type==='reel';const id='v19-'+Math.abs(seed);const art=reel?`<circle cx="52" cy="52" r="25" fill="none" stroke="${color}" stroke-width="7"/><circle cx="52" cy="52" r="14" fill="none" stroke="#effaff" stroke-width="3"/><circle cx="52" cy="52" r="5" fill="${color}"/><path d="M75 50L94 38 98 44 83 58M30 73L18 86" stroke="${color}" stroke-width="6" stroke-linecap="round"/><path d="M42 29L47 18 56 18 61 29" stroke="#e0eefa" stroke-width="4" fill="none"/>`:`<path d="M20 100Q48 62 75 13" fill="none" stroke="${color}" stroke-width="${4+seed%3}" stroke-linecap="round"/><path d="M31 83Q57 39 94 27" fill="none" stroke="#dff8ff" stroke-width="1.6" stroke-dasharray="4 3"/><path d="M38 75Q50 68 62 75Q70 83 59 91" fill="none" stroke="${color}" stroke-width="4"/><path d="M44 63L54 69 M57 43L68 51 M69 25L80 32" stroke="#ecfaff" stroke-width="2"/>`;
return `<span class="v19-gear-art ${extra||''}" role="img" aria-label="${esc(g.name||'Снасть')}"><svg viewBox="0 0 112 112" aria-hidden="true"><defs><radialGradient id="${id}"><stop stop-color="${color}" stop-opacity=".23"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></radialGradient></defs><circle cx="56" cy="56" r="53" fill="url(#${id})"/><g transform="rotate(${(seed%5-2)*4} 56 56)">${art}</g>${Array.from({length:3},(_,i)=>`<circle cx="${17+(seed+i*19)%80}" cy="${12+(seed+i*31)%86}" r="1.5" fill="${color}" opacity=".6"/>`).join('')}</svg></span>`}
itemArt=function(item,extra=''){if(item&&['rod','reel'].includes(item.type))return viva19GearSvg(item,extra);return viva19PriorArt(item,extra)};
const viva19OldCase=caseView;
caseView=function(){caseCount=Math.min(caseCount,5);viva19OldCase();const root=$('view');if(!root)return;root.classList.add('v19-case-screen');const result=$('case-results');const panel=$('case-open')?.closest('.panel');if(result&&panel){panel.append(result);result.classList.add('v19-result-stage');}root.querySelectorAll('button').forEach(b=>b.classList.add('v19-tap'));};
const viva19PreviousOpen=open11Case;
open11Case=async function(){if(lock)return;const view=$('view');const controls=[...view.querySelectorAll('button,input')];controls.forEach(x=>x.disabled=true);view.classList.add('v19-opening');try{await viva19PreviousOpen()}finally{view.classList.remove('v19-opening');if($('view')===view){controls.forEach(x=>{if(x.id!=='case-open')x.disabled=false});const open=$('case-open');if(open)open.disabled=false;const results=$('case-results');if(results){const actions=results.querySelector('.v17-case-actions');if(actions)results.append(actions);results.scrollIntoView=()=>{};}}}};
const viva19PriorBag=bagView;
bagView=function(){viva19PriorBag();$('view')?.classList.add('v19-bag');};
const viva19PriorFish=fishView;
fishView=function(){viva19PriorFish();$('view')?.classList.add('v19-fishing');};
