/* Read-only referral list and case choices; rewards are always verified by backend. */
const viva19OldScreen=vivaScreen;
vivaScreen=function(){viva19OldScreen();const root=$('view');if(!root||!viva14)return;
if(tab==='referral'){root.classList.add('v19-referral');const entries=viva14.invited_players||[];const panel=document.createElement('section');panel.className='v19-friends v14-card';panel.innerHTML=`<h2>👥 Приглашённые игроки <span>${entries.length}</span></h2>${entries.length?`<div class="v19-friend-list">${entries.map((x,i)=>`<div class="v19-friend"><span class="v19-friend-avatar">${i+1}</span><div><b>${esc(x.name)}</b><small>${new Date(x.created*1000).toLocaleDateString('ru-RU')} · #${x.id}</small></div><span class="v19-friend-check">✓</span></div>`).join('')}</div>`:'<p>Пока никого нет. Пригласи первого друга по своей ссылке!</p>'}`;root.querySelector('.v14-card')?.after(panel)}
if(tab==='partner'){root.classList.add('v19-partner');const old=$('v14-cases');if(old){const choices=(S.cases||[]).map(c=>`<option value="${esc(c.key)}">${esc(c.name)} · осталось ${c.amount||0}</option>`).join('');const picker=document.createElement('div');picker.className='v19-case-selector';picker.innerHTML=`<label>Кейсы для одного участника (до 3)<select id="v19-case1"><option value="">Без кейса</option>${choices}</select></label><label>Второй кейс<select id="v19-case2"><option value="">Без кейса</option>${choices}</select></label><label>Третий кейс<select id="v19-case3"><option value="">Без кейса</option>${choices}</select></label>`;old.before(picker);old.hidden=true;const button=old.parentElement.querySelector('button[onclick*="partner/promo"]');if(button)button.setAttribute('onclick',`vivaAction('partner/promo',{code:$('v14-code').value,coins:Number($('v14-money').value),uses:Number($('v14-uses').value),cases:[1,2,3].map(i=>$('v19-case'+i).value).filter(Boolean)})`);}}
};

// ===== layer: v20.js =====
/* V20 — screen behavior and aspect-safe fish artwork */
'use strict';
const v20Images=new Map();
const v20OldArt=itemArt;
itemArt=function(item,extra=''){
 if(item?.location&&item.art?.atlas?.startsWith('fish12_')&&String(extra).split(/\s+/).includes('collect-art')){
  const a=item.art;return `<span class="v20-fish-frame collect-art"><canvas class="v20-fish-canvas" data-v20-src="/assets/${esc(a.atlas)}.webp" data-v20-rect="${a.rect.join(',')}" aria-label="${esc(item.name)}" role="img"></canvas></span>`;
 }
 return v20OldArt(item,extra);
};
// Функция v20DrawFish: логика соответствующего элемента интерфейса.
function v20DrawFish(canvas){if(canvas.dataset.v20Drawn)return;canvas.dataset.v20Drawn='yes';const path=canvas.dataset.v20Src;let img=v20Images.get(path);if(!img){img=new Image();img.src=path;v20Images.set(path,img)}const draw=()=>{if(!canvas.isConnected)return;const [sx,sy,sw,sh]=canvas.dataset.v20Rect.split(',').map(Number);if(!sw||!sh)return;const width=300,height=190;canvas.width=width;canvas.height=height;let scale=Math.min(width/sw,height/sh)*.91;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,width,height);ctx.imageSmoothingQuality='high';ctx.drawImage(img,sx,sy,sw,sh,(width-sw*scale)/2,(height-sh*scale)/2,sw*scale,sh*scale)};if(img.complete&&img.naturalWidth)draw();else img.addEventListener('load',draw,{once:true})}
const v20Observer=new MutationObserver(()=>{document.querySelectorAll('canvas.v20-fish-canvas:not([data-v20-drawn])').forEach(v20DrawFish)});v20Observer.observe(document.getElementById('view'),{subtree:true,childList:true});v20Observer.observe(document.getElementById('modal'),{subtree:true,childList:true});
const v20OldBag=bagView;bagView=function(){v20OldBag();const v=$('view');v.classList.add('v20-bag');v.querySelectorAll('.bag-tabs button').forEach((b,i)=>{b.classList.add('v20-tab-'+i)});v.querySelectorAll('.collect-card').forEach(c=>c.classList.add('v20-bag-card'));v.querySelectorAll('canvas.v20-fish-canvas').forEach(v20DrawFish)};
const v20OldFish=fishView;fishView=function(){v20OldFish();const v=$('view');v.classList.add('v20-fishing');v.querySelectorAll('.quick-actions').forEach(el=>el.remove())};
const v20OldCase=caseView;caseView=function(){v20OldCase();const v=$('view');v.classList.add('v20-case-screen');const panel=$('case-open')?.closest('.panel');if(!panel)return;let art=panel.querySelector('.case-art');let stage=document.createElement('div');stage.className='v20-case-stage';stage.id='v20-case-stage';stage.innerHTML='<div class="v20-stage-caption">VIVA · КОЛЛЕКЦИЯ СНАРЯЖЕНИЯ</div>';if(art){art.remove();stage.append(art)}let controls=panel.querySelector('.bag-tabs');if(controls)panel.insertBefore(stage,controls);else panel.prepend(stage);const prior=$('case-results');if(prior)prior.hidden=true;};
const v20OpenPrior=open11Case;
open11Case=async function(){if(lock)return;const c=S.cases.find(c=>c.key===selectedCase);if(!c)return;lock=true;const count=caseCount;const view=$('view');const stage=$('v20-case-stage');const oldScroll=window.scrollY;const prior=(S.gear||[]).map(g=>({key:g.key,amount:g.amount||1}));view.classList.add('v20-case-screen');view.querySelectorAll('button,input').forEach(b=>b.disabled=true);stage.classList.add('is-active');stage.dataset.opening="true";
 try{
  const data=await api('/api/fishing/case/open',{case_key:c.key,revision:c.revision,count});
  const rewards=data.rewards||[];
  if(!caseFast&&count===1){let list=Array.from({length:30},(_,i)=>c.rewards[(i*13+7)%c.rewards.length]);list[25]=rewards[0].reward;stage.innerHTML=`<div class="v20-stage-caption">КЕЙС ОТКРЫВАЕТСЯ</div><div class="v20-rolling"><div class="v20-roll-strip">${list.map(g=>`<div class="v20-roll-item rarity-${esc(g.rarity||'common')}">${itemArt(g,'collect-art')}<span>${esc(g.name)}</span></div>`).join('')}</div><i class="v20-needle"></i></div>`;const strip=stage.querySelector('.v20-roll-strip');await new Promise(resolve=>{requestAnimationFrame(()=>{const winningCard=strip.children[25];const stopPart=.06+Math.random()*.88;const target=stage.querySelector('.v20-rolling').clientWidth/2-(winningCard.offsetLeft+winningCard.offsetWidth*stopPart);stage.style.setProperty('--v20-stop-part',stopPart.toFixed(3));const anim=strip.animate([{transform:'translateX(0px)'},{transform:`translateX(${target}px)`}],{duration:matchMedia('(prefers-reduced-motion:reduce)').matches?150:4100,easing:'cubic-bezier(.08,.6,.11,1)',fill:'forwards'});anim.finished.then(resolve).catch(resolve)})})
  }else{stage.innerHTML=`<div class="v20-stage-caption">ОТКРЫВАЕМ ${rewards.length} КЕЙСОВ</div><div class="v20-rewards">${rewards.map((x,i)=>`<div class="v20-reward rarity-${x.reward.rarity}" style="animation-delay:${i*180}ms">${itemArt(x.reward,'collect-art')}<b>${esc(x.reward.name)}</b></div>`).join('')}</div>`;await new Promise(resolve=>setTimeout(resolve,matchMedia('(prefers-reduced-motion:reduce)').matches?120:1200+rewards.length*130))}
  accept(data.state);paint();const fresh=$('v20-case-stage');if(!fresh)return;fresh.dataset.opening="false";const prev=Object.fromEntries(prior.map(g=>[g.key,g.amount]));const additions=[];for(const g of S.gear||[]){for(let i=0;i<(g.amount||1)-(prev[g.key]||0);i++)additions.push(g.key)}if(typeof v17RecentRewards!=='undefined')v17RecentRewards=additions;
  fresh.innerHTML=`<div class="v20-stage-caption">+${35*rewards.length} EXP · ПОЛУЧЕНО ${rewards.length}</div><h2>Твои награды</h2><div class="v20-rewards">${rewards.map((x,i)=>`<article class="v20-reward rarity-${x.reward.rarity}" style="animation-delay:${i*80}ms">${itemArt(x.reward,'collect-art')}<b>${esc(x.reward.name)}</b><small>${x.auto_sold?'Продан за '+fmt(x.compensation)+' $':'В рюкзаке'}</small></article>`).join('')}</div><div class="v20-stage-actions"><button onclick="caseView()">↻ Крутить ещё</button><button onclick="typeof v17KeepCases==='function'?v17KeepCases():go('bag')">✓ Оставить</button>${additions.length?'<button class="sell" onclick="v17SellCases()">Продать полученное</button>':''}</div>`;
  fresh.querySelectorAll('canvas.v20-fish-canvas').forEach(v20DrawFish);
  if(Math.abs(window.scrollY-oldScroll)>12)window.scrollTo({top:oldScroll,behavior:'instant'});
 }catch(e){if(stage)stage.innerHTML='<p class="v20-stage-caption">Не удалось открыть кейс: '+esc(e.message)+'</p>';if(Math.abs(window.scrollY-oldScroll)>12)window.scrollTo({top:oldScroll,behavior:'instant'})}finally{lock=false;stage?.removeAttribute('data-opening');const v=$('view');v?.querySelectorAll('button,input').forEach(el=>el.disabled=false)}
};

// ===== layer: v21.js =====
/* Viva V21 - Backpack visual redesign. Existing inventory actions remain server-backed. */
'use strict';
const viva21BagPrior=bagView;
bagView=function(){
  viva21BagPrior();
  const root=document.getElementById('view');
  if(!root || !S)return;
  root.classList.add('v21-backpack');
  root.dataset.bagSection=bagTab;
  root.dataset.gearCategory=bagTab==='gear'?category:'none';
  const title=root.querySelector('h1');
  if(title){
    const head=title.closest('.section-heading')||title.parentElement;
    head?.classList.add('v21-bag-heading');
    if(!head.querySelector('.v21-overline'))title.insertAdjacentHTML('beforebegin','<span class="v21-overline">VIVA / КОЛЛЕКЦИЯ</span>');
  }
  const sets=[
    {tab:'fish',label:'Улов',count:(S.catches||[]).length,icon:'🐟'},
    {tab:'gear',label:'Снасти',count:(S.gear||[]).reduce((n,g)=>n+(g.amount||1),0),icon:'🎣'},
    {tab:'tank',label:'Аквариум',count:(S.aquarium?.fish||[]).length,icon:'🫧'}
  ];
  const primary=root.querySelector('.bag-tabs');
  if(primary){
    primary.classList.add('v21-primary-tabs');
    [...primary.children].slice(0,3).forEach((el,i)=>{
      if(!sets[i])return;
      const s=sets[i];
      el.innerHTML=`<span class="v21-tab-icon">${s.icon}</span><span class="v21-tab-name">${s.label}</span><b class="v21-tab-count">${s.count}</b>`;
    });
  }
  if(bagTab==='gear'){
    const tabs=[...root.querySelectorAll('.bag-tabs')][1];
    if(tabs){tabs.classList.add('v21-gear-tabs');[...tabs.children].forEach(b=>{
      const val=(b.getAttribute('onclick')||'').match(/category='([^']+)'/)?.[1]||'';
      b.dataset.gear=val;
      const names={rod:'Удочки',reel:'Катушки',bait:'Приманки',line:'Леска',spoon:'Блёсны',spinner:'Вертушки',tackle:'Оснастка'};
      const icons={rod:'🎣',reel:'◉',bait:'◇',line:'〰',spoon:'✦',spinner:'✺',tackle:'⬡'};
      b.innerHTML=`<span class="v21-gear-icon">${icons[val]||'◆'}</span><span>${names[val]||b.textContent}</span>`;
    })}
  }
  const cards=[...root.querySelectorAll('.collection-grid > .collect-card')];
  cards.forEach((card,i)=>{
    card.classList.add('v21-item');
    card.style.setProperty('--v21-order',Math.min(i,12));
    if(bagTab==='gear')card.dataset.gear=category;
    let art=card.querySelector('.collect-art');
    if(art)art.classList.add('v21-item-art');
    const buttons=card.querySelectorAll('.card-actions button');
    buttons.forEach(b=>b.classList.add('v21-action'));
  });
  const loadout=root.querySelector('.loadout');if(loadout)loadout.classList.add('v21-loadout');
  root.querySelectorAll('.equipment-slot').forEach((slot,i)=>{
    slot.classList.add('v21-slot');
    slot.dataset.gear=Object.keys(labels).filter(k=>k!=='cases')[i]||'other';
  });
  const grid=root.querySelector('.collection-grid');if(grid)grid.classList.add('v21-collection');
  if(bagTab==='gear'&&grid&&!root.querySelector('.v21-collection-heading')){
    const heading=document.createElement('div');heading.className='v21-collection-heading';
    const names={rod:'Коллекция удочек',reel:'Коллекция катушек',bait:'Коллекция приманок',line:'Коллекция лесок',spoon:'Коллекция блёсен',spinner:'Коллекция вертушек'};
    heading.innerHTML=`<div><small>ИНВЕНТАРЬ</small><h2>${names[category]||'Мои снасти'}</h2></div><span>${(S.gear||[]).filter(g=>g.type===category).reduce((n,g)=>n+(g.amount||1),0)} / 6</span>`;
    grid.before(heading);
  }
  if(bagTab==='fish'&&grid&&!root.querySelector('.v21-collection-heading')){
    const heading=document.createElement('div');heading.className='v21-collection-heading';
    heading.innerHTML=`<div><small>ТВОИ ТРОФЕИ</small><h2>Пойманная рыба</h2></div><span>${(S.catches||[]).length} / 30</span>`;
    grid.before(heading);
  }
  root.querySelectorAll('canvas.v20-fish-canvas').forEach(v20DrawFish);
};


/* VIVA 2.0 · Figma-inspired skin · 2026-10-30
   Server game actions, case awards, and inventory remain handled by existing code. */
const vivaPreviousPaint=paint;
paint=function(){
  vivaPreviousPaint();
  if(!S || tab==='admin')return;
  const p=S.player||{},lv=S.level||{};
  const progress=Math.max(0,Math.min(100,100*(lv.level_xp||0)/Math.max(1,lv.next_xp||1)));
  $('header').innerHTML=`<button class="viva-avatar" style="--xp:${progress}%" onclick="go('profile')" aria-label="Мой профиль"><span class="viva-avatar-inner">${esc(p.avatar||'🎣')}</span></button><div class="viva-identity"><strong>${esc(p.nickname||p.telegram_name||'Рыбак')}</strong><small>${lv.level||1} ур.</small></div><div class="viva-balance">ⓢ ${fmt(p.coins||0)}</div>`;
  $('nav').innerHTML=[['fish','♧','Рыбалка'],['bag','▤','Рюкзак'],['shop','⬡','Кейсы'],['top','≋','Рейтинг'],['menu','•••','Меню']].map(([key,icon,name])=>`<button aria-label="${name}" title="${name}" class="${tab===key?'active':''}" onclick="go('${key}')"><span>${icon}</span></button>`).join('');
};

fishView=function(){
  const l=S.locations[loc],locked=(S.level?.level||1)<l.level;
  $('view').innerHTML=`<section class="viva-home"><div class="viva-hero"><div class="viva-hero-picture">${scene11(l)}</div><button class="viva-prev" onclick="move(-1)" aria-label="Предыдущая локация">‹</button><button class="viva-next" onclick="move(1)" aria-label="Следующая локация">›</button><div class="viva-hero-shade"><strong>${esc(l.name)}</strong><small>${locked?'🔒 Нужен уровень '+l.level:esc(l.subtitle||'Рыбацкая локация')}</small></div></div><div class="viva-club">Viva Рыбацкий Клуб</div><div class="viva-action-row"><button class="viva-bag-button" onclick="go('bag')" title="Рюкзак">♧</button><button class="viva-cast-button" id="cast" onclick="action('cast',{location:S.locations[loc].key})" ${locked?'disabled':''}>🎣 &nbsp; Ловить рыбу</button></div><div class="viva-attempts"><span>◴ &nbsp; Осталось попыток: <b>${S.attempts.remaining}/5</b></span><small id="attempts-timer">Восстановление</small></div><div class="viva-clover"><span>☘ &nbsp; Клевер ${S.buff?.active?'×'+S.buff.multiplier:''}</span><strong>${S.buff?.active?luckTime(S.buff.expires_at):'Не активен'}</strong></div><div class="viva-quick-tools"><button onclick="go('rewards')">🎁 Награды</button><button onclick="go('chat')">💬 Чат</button><button onclick="openEquipment('rod')">🎣 Снасти</button></div><details class="viva-detail"><summary>Рыбы локации и шансы</summary>${(S.fish_odds?.[l.key]||[]).map(f=>`<div class="odds-row"><span>${esc(f.name)}</span><b>${chanceText(f.chance)}</b></div>`).join('')}</details></section>`;
  let x=0;const scene=$('view').querySelector('.viva-hero-picture');
  scene.addEventListener('touchstart',e=>x=e.changedTouches[0].clientX,{passive:true});
  scene.addEventListener('touchend',e=>{let dx=e.changedTouches[0].clientX-x;if(Math.abs(dx)>45)move(dx<0?1:-1)},{passive:true});
  cooldown();
};

shopView=function(){
 if(selectedCase&&S.cases.some(c=>c.key===selectedCase))return caseView();
 $('view').innerHTML=`<h1 class="viva-page-title">Кейсы</h1><p class="viva-subtitle">Открой новые снасти для большой рыбалки</p><div class="viva-case-grid">${S.cases.map((c,i)=>`<article class="viva-case-tile" style="--tile:${['#229ce6','#aa59ee','#f18c41','#ef548c'][i%4]}"><div class="viva-tile-art">${['🎁','💎','🧰','✨'][i%4]}</div><b>${esc(c.name)}</b><small>${fmt(c.price)} $ · ${c.rewards.length} наград</small><button onclick="selectedCase='${c.key}';caseView()">Посмотреть</button></article>`).join('')}</div>`;
};

caseView=function(){
 const c=S.cases.find(c=>c.key===selectedCase);if(!c)return shopView();
 $('view').innerHTML=`<section class="viva-case-page"><div class="viva-case-head"><button onclick="selectedCase=null;shopView()" aria-label="Назад">‹</button><strong>${esc(c.name)}</strong><button onclick="document.getElementById('viva-case-contents').scrollIntoView({behavior:'smooth'})" aria-label="Содержимое кейса">ⓘ</button></div><div class="viva-case-showpiece"><div class="viva-case-glow">${ico(c.type)}</div><small>${c.amount?`У тебя: ${c.amount}`:'Открой кейс и получи снаряжение'}</small></div><div class="viva-case-purchase"><div class="viva-case-amount">${[1,3,5].map(n=>`<button class="${caseCount===n?'active':''}" onclick="caseCount=${n};caseView()">${n}X</button>`).join('')}</div><button class="viva-case-buy" id="case-open" onclick="open11Case()" ${!c.enabled?'disabled':''}><span>Открыть X${caseCount}</span><span>${fmt(Math.max(0,caseCount-c.amount)*c.price)} $</span></button></div><div id="case-results"></div><section class="viva-case-rewards" id="viva-case-contents"><h2>Возможные награды</h2><p>Точные шансы выпадения</p><div class="collection-grid">${c.rewards.map(g=>`<article class="collect-card rarity-${g.rarity}">${rarity(g)}${itemArt(g,'collect-art')}<strong>${esc(g.name)}</strong><small>${chanceText(g.chance)}</small></article>`).join('')}</div></section></section>`;
};

const vivaOldBagView=bagView;
bagView=function(){vivaOldBagView();const view=$('view');view.classList.add('viva-bag-screen');const heading=view.querySelector('h1');if(heading)heading.classList.add('viva-page-title');const grid=view.querySelector('.collection-grid');if(grid){grid.classList.add('viva-fish-grid');}const tabs=view.querySelector('.bag-tabs');if(tabs)tabs.classList.add('viva-bag-tabs');};
